import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { GoogleGenAI } from "@google/genai";
import { Bot, Sparkles, Send, Loader2 } from 'lucide-react';

const AICoach: React.FC = () => {
  const [goal, setGoal] = useState('');
  const [level, setLevel] = useState('Beginner');
  const [response, setResponse] = useState('');
  const [loading, setLoading] = useState(false);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!goal) return;

    setLoading(true);
    setResponse('');

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        You are IronPulse AI, an elite fitness coach. 
        The user has the following goal: "${goal}".
        Their experience level is: "${level}".

        Create a concise, high-intensity workout plan for them for ONE day. 
        Keep the tone motivating, intense, and professional. 
        Format the response with Markdown, using bold for exercise names.
        Include specific sets and reps.
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
      });

      setResponse(result.text || "Could not generate plan. Please try again.");
    } catch (error) {
      console.error("AI Error:", error);
      setResponse("System overload. Please check your connection and try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <section id="ai-coach" className="py-20 bg-zinc-900 border-y border-zinc-800 relative overflow-hidden">
      {/* Background Tech Elements */}
      <div className="absolute top-0 left-0 w-full h-full opacity-5 pointer-events-none overflow-hidden">
         <div className="absolute top-10 left-10 w-64 h-64 border border-lime-500 rounded-full animate-ping"></div>
         <div className="absolute bottom-10 right-10 w-96 h-96 border border-cyan-500 rounded-full animate-pulse"></div>
      </div>

      <div className="container mx-auto px-4 relative z-10">
        <div className="text-center mb-12">
            <div className="inline-flex items-center gap-2 px-4 py-1 rounded-full bg-zinc-800 border border-zinc-700 mb-4">
                <Sparkles className="w-4 h-4 text-lime-400" />
                <span className="text-xs font-bold text-white uppercase tracking-wider">Powered by Gemini AI</span>
            </div>
            <h2 className="text-4xl md:text-5xl font-heading font-bold text-white mb-4">
            AI <span className="text-transparent bg-clip-text bg-gradient-to-r from-lime-400 to-cyan-400">Performance Coach</span>
            </h2>
            <p className="text-zinc-400 max-w-xl mx-auto">
            Access our backend intelligence. Input your goals, and get an instant, elite-level daily workout structure tailored to you.
            </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-start max-w-6xl mx-auto">
            {/* Input Form */}
            <motion.div 
                initial={{ opacity: 0, x: -30 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                className="bg-zinc-950 p-8 border border-zinc-800 rounded-xl relative group"
            >
                <div className="absolute inset-0 bg-gradient-to-br from-lime-500/5 to-cyan-500/5 rounded-xl"></div>

                <form onSubmit={handleGenerate} className="relative z-10 space-y-6">
                    <div>
                        <label className="block text-zinc-400 text-sm font-bold uppercase mb-2">Target Goal</label>
                        <input 
                            type="text" 
                            value={goal}
                            onChange={(e) => setGoal(e.target.value)}
                            placeholder="e.g. Build chest size, 30 min cardio..."
                            className="w-full bg-zinc-900 border border-zinc-700 p-4 text-white placeholder-zinc-600 focus:outline-none focus:border-lime-400 transition-colors rounded-lg"
                        />
                    </div>

                    <div>
                        <label className="block text-zinc-400 text-sm font-bold uppercase mb-2">Experience Level</label>
                        <div className="grid grid-cols-3 gap-2">
                            {['Beginner', 'Intermediate', 'Advanced'].map((lvl) => (
                                <button
                                    key={lvl}
                                    type="button"
                                    onClick={() => setLevel(lvl)}
                                    className={`py-3 text-sm font-bold uppercase rounded-lg border transition-all ${
                                        level === lvl 
                                        ? 'bg-lime-500 text-black border-lime-500' 
                                        : 'bg-zinc-900 text-zinc-500 border-zinc-700 hover:border-zinc-500'
                                    }`}
                                >
                                    {lvl}
                                </button>
                            ))}
                        </div>
                    </div>

                    <button 
                        type="submit" 
                        disabled={loading || !goal}
                        className="w-full py-4 bg-gradient-to-r from-lime-500 to-lime-400 text-black font-bold uppercase tracking-widest hover:brightness-110 transition-all rounded-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(132,204,22,0.3)]"
                    >
                        {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Bot className="w-5 h-5" />}
                        {loading ? 'Analyzing Data...' : 'Generate Workout'}
                    </button>
                </form>
            </motion.div>

            {/* Output Display */}
            <motion.div 
                initial={{ opacity: 0, x: 30 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                className="min-h-[400px] bg-zinc-950 border border-zinc-800 rounded-xl p-8 relative overflow-hidden flex flex-col"
            >
                 {response ? (
                    <div className="prose prose-invert max-w-none">
                        <div className="flex items-center gap-3 mb-6 pb-6 border-b border-zinc-800">
                             <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center text-cyan-400">
                                <Bot className="w-6 h-6" />
                             </div>
                             <div>
                                 <h4 className="text-white font-bold font-heading uppercase">IronMind Plan</h4>
                                 <p className="text-xs text-zinc-500 uppercase">Generated just now</p>
                             </div>
                        </div>
                        <div className="whitespace-pre-wrap text-zinc-300 font-light leading-relaxed">
                            {response}
                        </div>
                    </div>
                 ) : (
                     <div className="flex-1 flex flex-col items-center justify-center text-zinc-600">
                        <Bot className="w-16 h-16 mb-4 opacity-20" />
                        <p className="text-center max-w-xs text-sm uppercase tracking-wide opacity-50">
                            Awaiting Input parameters. <br/>
                            Connect to backend intelligence to receive coaching.
                        </p>
                     </div>
                 )}

                 {/* Decorative Corner lines */}
                 <div className="absolute top-0 right-0 w-16 h-16 border-t-2 border-r-2 border-lime-500/20 rounded-tr-xl"></div>
                 <div className="absolute bottom-0 left-0 w-16 h-16 border-b-2 border-l-2 border-cyan-500/20 rounded-bl-xl"></div>
            </motion.div>
        </div>
      </div>
    </section>
  );
};

export default AICoach;

