import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageCircle, X, Send, Bot, User, Loader2 } from 'lucide-react';
import { GoogleGenAI, Chat } from "@google/genai";

interface Message {
  role: 'user' | 'model';
  text: string;
}

const GymBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Namaste! I am PulseBot. Ask me about our memberships (₹), equipment, or workout tips!' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSessionRef = useRef<Chat | null>(null);

  // Initialize Chat Session
  useEffect(() => {
    if (!chatSessionRef.current) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        chatSessionRef.current = ai.chats.create({
            model: 'gemini-2.5-flash',
            config: {
                systemInstruction: `
                    You are PulseBot, the dedicated AI receptionist and coach for IronPulse Fitness in India.

                    TRAINING DATA & KNOWLEDGE BASE:
                    1. Identity: You are energetic, professional, and motivating. Use emojis occasionally (💪, 🔥).
                    2. Pricing (India): 
                       - Monthly Membership: ₹1,999/mo (Gym access, Locker, Wifi)
                       - Quarterly Membership: ₹4,999/3mo (Includes Unlimited Classes)
                       - Annual Membership: ₹14,999/yr (Best Value, includes Personal Training sessions)
                    3. Programs:
                       - The Shredder 30: ₹5,999 (30 Days fat loss)
                       - Hypertrophy Max: ₹11,999 (12 Weeks muscle gain)
                       - Athlete Performance: ₹29,999 (6 Months advanced)
                    4. Facilities: Open 24/7, high-end Technogym equipment, sauna, steam room.
                    5. Role: Answer questions about membership, give quick workout advice, or explain exercises.

                    CONSTRAINT: Keep answers concise (under 3 sentences) unless the user asks for a detailed plan.
                    If asked about prices not listed here, say you only have the standard rates and they should visit the desk for custom packages.
                `,
            }
        });
    }
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || !chatSessionRef.current) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        const result = await chatSessionRef.current.sendMessage({ message: userMsg });
        setMessages(prev => [...prev, { role: 'model', text: result.text || "Let's crush it! (System error, try again)" }]);
    } catch (error) {
        console.error("Bot Error", error);
        setMessages(prev => [...prev, { role: 'model', text: "Network glitch! Check your connection. 💪" }]);
    } finally {
        setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Button */}
      <motion.button
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full shadow-[0_0_20px_rgba(132,204,22,0.5)] transition-colors ${isOpen ? 'hidden' : 'bg-lime-500 text-black'}`}
      >
        <MessageCircle className="w-8 h-8" />
      </motion.button>

      {/* Chat Window */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 100, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 100, scale: 0.9 }}
            className="fixed bottom-6 right-6 z-50 w-[90vw] md:w-[350px] h-[500px] bg-zinc-950 border border-zinc-800 rounded-2xl shadow-2xl flex flex-col overflow-hidden"
          >
            {/* Header */}
            <div className="p-4 bg-zinc-900 border-b border-zinc-800 flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-lime-500 flex items-center justify-center">
                        <Bot className="w-6 h-6 text-black" />
                    </div>
                    <div>
                        <h3 className="font-heading font-bold text-white">PulseBot</h3>
                        <div className="flex items-center gap-1">
                            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                            <span className="text-xs text-zinc-400">Online 24/7</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className="text-zinc-500 hover:text-white transition-colors"
                >
                    <X className="w-6 h-6" />
                </button>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-black/50">
                {messages.map((msg, idx) => (
                    <div 
                        key={idx} 
                        className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
                    >
                        <div className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center ${msg.role === 'user' ? 'bg-zinc-800' : 'bg-lime-500/20'}`}>
                            {msg.role === 'user' ? <User className="w-4 h-4 text-zinc-400" /> : <Bot className="w-4 h-4 text-lime-400" />}
                        </div>
                        <div className={`p-3 rounded-2xl max-w-[80%] text-sm leading-relaxed ${
                            msg.role === 'user' 
                            ? 'bg-zinc-800 text-white rounded-tr-none' 
                            : 'bg-zinc-900 border border-zinc-800 text-zinc-200 rounded-tl-none'
                        }`}>
                            {msg.text}
                        </div>
                    </div>
                ))}
                {isLoading && (
                    <div className="flex gap-3">
                        <div className="w-8 h-8 rounded-full bg-lime-500/20 flex-shrink-0 flex items-center justify-center">
                            <Bot className="w-4 h-4 text-lime-400" />
                        </div>
                        <div className="bg-zinc-900 border border-zinc-800 p-3 rounded-2xl rounded-tl-none">
                            <Loader2 className="w-4 h-4 animate-spin text-lime-400" />
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <form onSubmit={handleSend} className="p-3 bg-zinc-900 border-t border-zinc-800 flex gap-2">
                <input 
                    type="text" 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Ask about prices or exercises..."
                    className="flex-1 bg-zinc-950 border border-zinc-800 rounded-full px-4 text-sm text-white focus:outline-none focus:border-lime-500 transition-colors"
                />
                <button 
                    type="submit" 
                    disabled={isLoading || !input.trim()}
                    className="w-10 h-10 bg-lime-500 rounded-full flex items-center justify-center text-black hover:bg-lime-400 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                    <Send className="w-4 h-4" />
                </button>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

export default GymBot;

