                       - Cancellation: 30-day notice required via email to info@fitnesshub.fit.
                       - Guest Policy: Quarterly/Annual members get 2 guest passes/month. Otherwise ₹500/visit.
                       - Dress Code: Athletic wear required. No jeans or open-toed shoes while lifting.

                    === INSTRUCTIONS ===
                    - Answer user queries using the database above.
                    - If asked for a workout, generate a SHORT text-based plan (e.g., "Here is a quick Chest workout...").
                    - Keep responses concise (max 3-4 sentences) unless a detailed plan is requested.
                    - If the user asks something not in the database (like specific medical advice), kindly refuse and suggest a doctor.
                `,
            }
        });
    }
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || !chatSessionRef.current) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        const result = await chatSessionRef.current.sendMessage({ message: userMsg });
        setMessages(prev => [...prev, { role: 'model', text: result.text || "System overload! Try again later." }]);
    } catch (error) {
        console.error("Bot Error", error);
        setMessages(prev => [...prev, { role: 'model', text: "Connection error. Please check your internet. 🔌" }]);
    } finally {
        setIsLoading(false);
    }
  };

  return (
    <>
      {/* Floating Button with Pulse Effect */}
      <motion.button
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full shadow-[0_0_20px_rgba(132,204,22,0.6)] transition-colors ${isOpen ? 'hidden' : 'bg-gradient-to-r from-lime-500 to-lime-400 text-black'}`}
      >
        <div className="absolute inset-0 rounded-full animate-ping bg-lime-500 opacity-20"></div>
        <MessageCircle className="w-8 h-8 relative z-10" />
      </motion.button>

      {/* Chat Window */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 100, scale: 0.9, rotateX: 20 }}
            animate={{ opacity: 1, y: 0, scale: 1, rotateX: 0 }}
            exit={{ opacity: 0, y: 100, scale: 0.9, rotateX: 20 }}
            transition={{ type: "spring", damping: 20, stiffness: 100 }}
            className="fixed bottom-6 right-6 z-50 w-[90vw] md:w-[380px] h-[600px] bg-zinc-950/95 backdrop-blur-xl border border-lime-500/30 rounded-2xl shadow-2xl flex flex-col overflow-hidden perspective-1000"
          >
            {/* Header */}
            <div className="p-4 bg-zinc-900/80 border-b border-zinc-800 flex justify-between items-center relative overflow-hidden">
                <div className="absolute inset-0 bg-lime-500/5"></div>
                <div className="flex items-center gap-3 relative z-10">
                    <div className="w-12 h-12 rounded-full bg-gradient-to-br from-lime-400 to-lime-600 flex items-center justify-center shadow-lg shadow-lime-500/20">
                        <Bot className="w-7 h-7 text-black" />
                    </div>
                    <div>
                        <h3 className="font-heading font-bold text-white text-lg tracking-wide">HubBot AI</h3>
                        <div className="flex items-center gap-1.5">
                            <span className="w-2 h-2 bg-lime-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(132,204,22,0.8)]"></span>
                            <span className="text-xs text-lime-400/80 font-bold uppercase">System Online</span>
                        </div>
                    </div>
                </div>
                <button 
                    onClick={() => setIsOpen(false)}
                    className="text-zinc-500 hover:text-white transition-colors relative z-10 hover:rotate-90 duration-300"
                >
                    <X className="w-6 h-6" />
                </button>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gradient-to-b from-black/80 to-zinc-950/80">
                {messages.map((msg, idx) => (
                    <motion.div 
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        key={idx} 
                        className={`flex gap-3 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}
                    >
                        <div className={`w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center shadow-md ${msg.role === 'user' ? 'bg-zinc-800' : 'bg-lime-500/20'}`}>
                            {msg.role === 'user' ? <User className="w-4 h-4 text-zinc-400" /> : <Bot className="w-4 h-4 text-lime-400" />}
                        </div>
                        <div className={`p-3 rounded-2xl max-w-[85%] text-sm leading-relaxed shadow-lg ${
                            msg.role === 'user' 
                            ? 'bg-zinc-800 text-white rounded-tr-none border border-zinc-700' 
                            : 'bg-zinc-900 border border-lime-500/20 text-zinc-200 rounded-tl-none'
                        }`}>
                            {msg.text.split('\n').map((line, i) => <p key={i} className="mb-1 last:mb-0">{line}</p>)}
                        </div>
                    </motion.div>
                ))}
                {isLoading && (
                    <div className="flex gap-3">
                        <div className="w-8 h-8 rounded-full bg-lime-500/20 flex-shrink-0 flex items-center justify-center">
                            <Bot className="w-4 h-4 text-lime-400" />
                        </div>
                        <div className="bg-zinc-900 border border-lime-500/20 p-3 rounded-2xl rounded-tl-none flex items-center gap-2">
                            <span className="text-xs text-lime-500 font-bold uppercase">Processing</span>
                            <Loader2 className="w-4 h-4 animate-spin text-lime-400" />
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <form onSubmit={handleSend} className="p-4 bg-zinc-900 border-t border-zinc-800 flex gap-2">
                <input 
                    type="text" 
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Ask about schedule, diet, exercises..."
                    className="flex-1 bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-sm text-white focus:outline-none focus:border-lime-500 focus:ring-1 focus:ring-lime-500/50 transition-all placeholder-zinc-600 shadow-inner"
                />
                <button 
                    type="submit" 
                    disabled={isLoading || !input.trim()}
                    className="w-12 h-12 bg-lime-500 rounded-xl flex items-center justify-center text-black hover:bg-lime-400 hover:scale-105 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-[0_0_15px_rgba(132,204,22,0.3)]"
                >
                    <Send className="w-5 h-5" />
                </button>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

