            <motion.div 
                initial={{ opacity: 0, x: 30 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                className="min-h-[400px] bg-zinc-950 border border-zinc-800 rounded-xl p-8 relative overflow-hidden flex flex-col shadow-2xl"
            >
                 {response ? (
