import React, { useState, useEffect } from 'react';
import { Dumbbell, Menu, X, Sparkles, User, LogIn } from 'lucide-react';
import Footer from './Footer';

interface LayoutProps {
  children: React.ReactNode;
  currentPage: string;
  onNavigate: (page: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, currentPage, onNavigate }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', href: '#home', page: 'home' },
    { name: 'Programs', href: '#programs', page: 'home' },
    { name: 'AI Coach', href: '#ai-coach', page: 'home' },
    { name: 'Pricing', href: '#pricing', page: 'home' },
    { name: 'Contact', href: '#contact', page: 'home' },
  ];

  const handleNavClick = (e: React.MouseEvent, link: any) => {
    if (currentPage !== 'home' && link.page === 'home') {
        e.preventDefault();
        onNavigate('home');
        // Small timeout to allow render before scrolling
        setTimeout(() => {
            const element = document.querySelector(link.href);
            if (element) element.scrollIntoView({ behavior: 'smooth' });
        }, 100);
    }
    setIsMobileMenuOpen(false);
  };

  return (
    <div className="min-h-screen flex flex-col bg-black text-white selection:bg-lime-500 selection:text-black">
      <nav className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${isScrolled ? 'bg-black/90 backdrop-blur-md border-b border-zinc-800 py-4' : 'bg-transparent py-6'}`}>
        <div className="container mx-auto px-6 flex justify-between items-center">
          <button onClick={() => onNavigate('home')} className="flex items-center gap-2 group outline-none">
            <div className="relative">
                <Dumbbell className="w-8 h-8 text-lime-400 group-hover:rotate-45 transition-transform relative z-10" />
                <div className="absolute inset-0 bg-lime-400 blur-lg opacity-40 group-hover:opacity-60 transition-opacity"></div>
            </div>
            <span className="text-2xl font-heading font-bold text-white tracking-tighter">
              MYFITNESS<span className="text-lime-400">HUB</span>
            </span>
          </button>

          {/* Desktop Nav */}
          <div className="hidden lg:flex gap-12 items-center">
            {navLinks.map((link) => (
              <a 
                key={link.name} 
                href={link.page === 'home' && currentPage === 'home' ? link.href : '#'}
                onClick={(e) => handleNavClick(e, link)}
                className={`text-sm font-bold uppercase tracking-wider transition-colors flex items-center gap-1.5 cursor-pointer ${link.name === 'AI Coach' ? 'text-cyan-400 hover:text-cyan-300' : 'text-zinc-300 hover:text-lime-400'}`}
              >
                {link.name === 'AI Coach' && <Sparkles className="w-3.5 h-3.5" />}
                {link.name}
              </a>
            ))}

            <div className="flex items-center gap-4 ml-4 pl-4 border-l border-zinc-800">
                <button 
                    onClick={() => onNavigate('login')}
                    className="text-white hover:text-lime-400 font-bold text-sm uppercase flex items-center gap-2"
                >
                    <LogIn className="w-4 h-4" /> Login
                </button>
                <button 
                    onClick={() => onNavigate('signup')}
                    className="px-6 py-2 bg-lime-500 text-black font-bold uppercase text-sm tracking-wide hover:bg-white transition-colors skew-x-[-10deg]"
                >
                    <span className="block skew-x-[10deg]">Join Now</span>
                </button>
            </div>
          </div>

          {/* Mobile Toggle */}
          <button 
            className="lg:hidden text-white hover:text-lime-400 transition-colors"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          >
            {isMobileMenuOpen ? <X /> : <Menu />}
          </button>
        </div>

        {/* Mobile Menu */}
        {isMobileMenuOpen && (
          <div className="lg:hidden absolute top-full left-0 w-full bg-zinc-950 border-b border-zinc-800 py-4 px-4 flex flex-col gap-4">
            {navLinks.map((link) => (
              <a 
                key={link.name} 
                href={link.page === 'home' && currentPage === 'home' ? link.href : '#'}
                onClick={(e) => handleNavClick(e, link)}
                className="text-lg font-heading font-bold uppercase text-zinc-300 hover:text-lime-400"
              >
                {link.name}
              </a>
            ))}
            <div className="flex flex-col gap-3 mt-4 pt-4 border-t border-zinc-800">
                <button 
                    onClick={() => { onNavigate('login'); setIsMobileMenuOpen(false); }}
                    className="w-full py-3 bg-zinc-800 text-white font-bold uppercase tracking-wide hover:bg-zinc-700"
                >
                    Login
                </button>
                <button 
                    onClick={() => { onNavigate('signup'); setIsMobileMenuOpen(false); }}
                    className="w-full py-3 bg-lime-500 text-black font-bold uppercase tracking-wide hover:bg-lime-400"
                >
                    Join Now
                </button>
            </div>
          </div>
        )}
      </nav>

      <main className="flex-grow">
        {children}
      </main>

      {currentPage === 'home' && <Footer />}
    </div>
  );
};

export default Layout;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Hero from './components/Hero';
import About from './components/About';
import Services from './components/Services';
import Programs from './components/Programs';
import AICoach from './components/AICoach';
import Testimonials from './components/Testimonials';
import Pricing from './components/Pricing';
import Contact from './components/Contact';
import GymBot from './components/GymBot';
import Login from './components/Login';
import Signup from './components/Signup';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('home');

  return (
    <Layout currentPage={currentPage} onNavigate={setCurrentPage}>
      {currentPage === 'home' && (
        <>
          <Hero />
          <About />
          <Services />
          <Programs />
          <AICoach />
          {/* Gallery removed as per request */}
          <Testimonials />
          <Pricing />
          <Contact />
          <GymBot />
        </>
      )}

      {currentPage === 'login' && <Login onNavigate={setCurrentPage} />}
      {currentPage === 'signup' && <Signup onNavigate={setCurrentPage} />}
    </Layout>
  );
};

export default App;

