const Signup: React.FC<SignupProps> = ({ onNavigate }) => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [successState, setSuccessState] = useState<'none' | 'confirmation_required' | 'complete'>('none');
  const [passwordStrength, setPasswordStrength] = useState(0);

  const calculateStrength = (pass: string) => {
    let score = 0;
    if (pass.length >= 6) score++;
    if (pass.length >= 10) score++;
    if (/[A-Z]/.test(pass)) score++;
    if (/[0-9]/.test(pass)) score++;
    return score; // Max 4
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });

    if (name === 'password') {
        setPasswordStrength(calculateStrength(value));
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { data, error } = await supabase.auth.signUp({
        email: formData.email,
        password: formData.password,
        options: {
          data: {
            first_name: formData.firstName,
            last_name: formData.lastName,
          },
        },
      });

      if (error) throw error;

      if (data?.user && !data?.session) {
        // User created but session is null -> Email confirmation required
        setSuccessState('confirmation_required');
      } else {
        // User created and session exists -> Auto login
        setSuccessState('complete');
        setTimeout(() => {
            onNavigate('home');
        }, 2000);
      }

    } catch (err: any) {
      setError(err.message || 'Failed to create account');
    } finally {
      setLoading(false);
    }
  };

  if (successState === 'confirmation_required') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-zinc-900 border border-yellow-500/50 p-8 rounded-2xl text-center max-w-md w-full"
            >
                <div className="w-16 h-16 bg-yellow-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Mail className="w-8 h-8 text-yellow-500" />
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">Check Your Email</h2>
                <p className="text-zinc-400 text-sm mb-6 leading-relaxed">
                    We have sent a confirmation link to <span className="text-white font-bold">{formData.email}</span>. 
                    Please verify your email address before logging in.
                </p>
                <button 
                    onClick={() => onNavigate('login')}
                    className="w-full bg-yellow-500 text-black font-bold uppercase py-3 rounded-lg hover:bg-yellow-400 transition-colors"
                >
                    Go to Login
                </button>
            </motion.div>
        </div>
      );
  }

  if (successState === 'complete') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-zinc-900 border border-lime-500 p-8 rounded-2xl text-center max-w-sm w-full"
            >
                <CheckCircle className="w-16 h-16 text-lime-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">Account Created!</h2>
                <p className="text-zinc-400 text-sm mb-4">Redirecting you...</p>
                <Loader2 className="w-5 h-5 animate-spin text-lime-500 mx-auto" />
            </motion.div>
        </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-900 px-4 relative overflow-hidden">
       {/* Background Ambience */}
      <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-[-20%] left-[-10%] w-[600px] h-[600px] bg-cyan-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md bg-zinc-950 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10"
      >
        <button 
            onClick={() => onNavigate('home')}
            className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors"
        >
            <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="text-center mb-8 mt-4">
            <div className="flex justify-center mb-4">
                <Dumbbell className="w-12 h-12 text-cyan-400" />
            </div>
            <h2 className="text-3xl font-heading font-bold text-white mb-2">Join the Hub</h2>
            <p className="text-zinc-400 text-sm">Start your transformation today.</p>
        </div>

        {error && (
            <div className="mb-4 p-3 bg-red-500/10 border border-red-500/50 rounded-lg flex items-center gap-2 text-red-400 text-sm">
