        <form onSubmit={handleSignup} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">First Name</label>
                    <input 
                        name="firstName"
