                        placeholder="Doe"
                    />
                </div>
            </div>

            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Email Address</label>
                <input 
                    name="email"
                    type="email" 
                    required
                    autoComplete="email"
                    value={formData.email}
                    onChange={handleChange}
                    className="w-full bg-zinc-900 border border-zinc-800 rounded-lg p-3 text-white focus:outline-none focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500 transition-all"
                    placeholder="you@example.com"
                />
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Password</label>
                <input 
                    name="password"
                    type="password" 
                    required
                    autoComplete="new-password"
