import { PricingPlan } from '../types';
import { supabase } from '../lib/supabaseClient';

interface CheckoutProps {
  plan: PricingPlan;
  onNavigate: (page: string) => void;
}

const Checkout: React.FC<CheckoutProps> = ({ plan, onNavigate }) => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: '',
    phone: '',
    street: '',
    city: '',
    zip: '',
  });
  const [user, setUser] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');
  const [passwordStrength, setPasswordStrength] = useState(0);

  // Check if user is already logged in
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        setUser(session.user);
        setFormData(prev => ({
          ...prev,
          email: session.user.email || '',
          firstName: session.user.user_metadata?.first_name || '',
          lastName: session.user.user_metadata?.last_name || '',
        }));
      }
    });
  }, []);

  const calculateStrength = (pass: string) => {
    let score = 0;
    if (pass.length >= 6) score++;
    if (pass.length >= 10) score++;
    if (/[A-Z]/.test(pass)) score++;
    if (/[0-9]/.test(pass)) score++;
    return score; // Max 4
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });

    if (name === 'password') {
        setPasswordStrength(calculateStrength(value));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setStatus('idle');
    setErrorMessage('');

    try {
      // 1. Create Auth User if not logged in
      if (!user) {
          if (!formData.password || formData.password.length < 6) {
              throw new Error('Password is required (min 6 chars) to create your account.');
          }

          const { data: authData, error: authError } = await supabase.auth.signUp({
              email: formData.email,
              password: formData.password,
              options: {
                  data: {
                      first_name: formData.firstName,
                      last_name: formData.lastName,
                  }
              }
          });

          if (authError) throw authError;
      }

      // 2. Create Subscription Record in Database
      const numericPrice = parseFloat(plan.price.replace(/[^0-9.]/g, ''));

      const { data, error } = await supabase
        .from('gym_subscriptions')
        .insert([
          {
            first_name: formData.firstName,
            last_name: formData.lastName,
            email: formData.email,
            phone_number: formData.phone,
            street_address: formData.street,
            city: formData.city,
            zip_code: formData.zip,
            membership_plan: plan.name,
            total_paid: numericPrice,
          },
