                </div>
            </div>

            <div className="flex justify-end">
                <button 
                    type="button" 
                    onClick={() => onNavigate('forgot-password')} 
                    className="text-xs text-lime-400 hover:underline"
                >
                    Forgot Password?
                </button>
            </div>

            <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-lime-500 text-black font-bold uppercase py-3 rounded-lg hover:bg-lime-400 transition-colors shadow-[0_0_15px_rgba(132,204,22,0.3)] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Login'}
