import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { ShieldCheck, ArrowLeft, Loader2, AlertCircle, Eye, EyeOff, Lock } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface AdminLoginProps {
    onNavigate: (page: string) => void;
}

const AdminLogin: React.FC<AdminLoginProps> = ({ onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Basic client-side check for demo purposes (In production, use RLS/Roles)
    if (!email.includes('admin') && !email.includes('myfitnesshub')) {
         setError('Access Denied: You do not have administrator privileges.');
         return;
    }

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email: email.trim(),
        password,
      });

      if (error) throw error;

      onNavigate('admin-dashboard');
    } catch (err: any) {
      console.error('Admin Login error:', err);
      if (err.message === 'Invalid login credentials') {
         setError('Invalid admin credentials.');
      } else {
         setError(err.message || 'Failed to login');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4 relative overflow-hidden">
      {/* Background Ambience - Red/Dark for Admin */}
      <div className="absolute top-[-20%] left-[-10%] w-[600px] h-[600px] bg-red-900/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="w-full max-w-md bg-zinc-900 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10"
      >
        <button 
            onClick={() => onNavigate('home')}
            className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors"
        >
            <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="text-center mb-8 mt-4">
            <div className="flex justify-center mb-4">
                <div className="w-16 h-16 bg-red-500/10 rounded-full flex items-center justify-center border border-red-500/30">
                     <ShieldCheck className="w-8 h-8 text-red-500" />
                </div>
            </div>
            <h2 className="text-3xl font-heading font-bold text-white mb-2">Admin Portal</h2>
            <p className="text-zinc-400 text-sm">Restricted Access Only.</p>
        </div>

        {error && (
            <div className="mb-4 p-3 bg-red-500/10 border border-red-500/50 rounded-lg flex items-start gap-2 text-red-400 text-sm">
                <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" /> 
                <span>{error}</span>
            </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Admin Email</label>
                <input 
                    type="email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    className="w-full bg-zinc-950 border border-zinc-800 rounded-lg p-3 text-white focus:outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 transition-all"
                    placeholder="admin@myfitnesshub.fit"
                />
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Password</label>
                <div className="relative">
                    <input 
                        type={showPassword ? "text" : "password"}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                        className="w-full bg-zinc-950 border border-zinc-800 rounded-lg p-3 pr-10 text-white focus:outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 transition-all"
                        placeholder="••••••••"
                    />
                    <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute right-3 top-3.5 text-zinc-500 hover:text-white transition-colors"
                        tabIndex={-1}
                    >
                        {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                    </button>
                </div>
            </div>

            <button 
                type="submit" 
                disabled={loading}
