                    <Shield className="w-6 h-6 text-red-500" />
                    <h1 className="text-xl font-heading font-bold">Admin<span className="text-red-500">Panel</span></h1>
                </div>
                <div className="flex items-center gap-4">
                    <span className="text-xs text-zinc-500 hidden md:block">admin@myfitnesshub.fit</span>
                    <button 
                        onClick={handleLogout}
