                    <div className="flex justify-between items-start mb-4">
                        <div>
                            <p className="text-zinc-400 text-xs font-bold uppercase">Total Revenue</p>
                            <h3 className="text-2xl font-bold text-white mt-1">{formatCurrency(stats.revenue)}</h3>
