                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Email Address</label>
                <input 
                    type="email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    autoComplete="email"
                    className="w-full bg-zinc-950 border border-zinc-800 rounded-lg p-3 text-white focus:outline-none focus:border-lime-500 focus:ring-1 focus:ring-lime-500 transition-all"
                    placeholder="you@example.com"
                />
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Password</label>
                <div className="relative">
                    <input 
                        type={showPassword ? "text" : "password"}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                        autoComplete="current-password"
                        className="w-full bg-zinc-950 border border-zinc-800 rounded-lg p-3 pr-10 text-white focus:outline-none focus:border-lime-500 focus:ring-1 focus:ring-lime-500 transition-all"
                        placeholder="••••••••"
                    />
                    <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute right-3 top-3.5 text-zinc-500 hover:text-white transition-colors"
                        tabIndex={-1}
                    >
                        {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                    </button>
                </div>
            </div>

            <div className="flex justify-end">
                <button 
                    type="button" 
                    onClick={() => onNavigate('forgot-password')} 
                    className="text-xs text-lime-400 hover:underline"
                >
                    Forgot Password?
                </button>
            </div>

            <button 
                type="submit" 
                disabled={loading}
                className="w-full bg-lime-500 text-black font-bold uppercase py-3 rounded-lg hover:bg-lime-400 transition-colors shadow-[0_0_15px_rgba(132,204,22,0.3)] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Login'}
            </button>
        </form>

        <div className="mt-6 text-center text-sm text-zinc-500">
            Don't have an account? 
            <button onClick={() => onNavigate('signup')} className="text-white font-bold ml-1 hover:text-lime-400 underline">Sign Up</button>
        </div>

        <div className="mt-8 pt-6 border-t border-zinc-800 text-center">
             <button 
                onClick={() => onNavigate('admin-login')} 
                className="text-xs text-zinc-600 hover:text-red-500 transition-colors flex items-center justify-center gap-1 mx-auto"
            >
                <ShieldCheck className="w-3 h-3" /> Admin Access
            </button>
        </div>
      </motion.div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Hero from './components/Hero';
import About from './components/About';
import Services from './components/Services';
import Programs from './components/Programs';
import AICoach from './components/AICoach';
import Testimonials from './components/Testimonials';
import Pricing from './components/Pricing';
import Contact from './components/Contact';
import Login from './components/Login';
import Signup from './components/Signup';
import Checkout from './components/Checkout';
import Dashboard from './components/Dashboard';
import ForgotPassword from './components/ForgotPassword';
import UpdatePassword from './components/UpdatePassword';
import AdminLogin from './components/AdminLogin';
import AdminDashboard from './components/AdminDashboard';
import { PricingPlan } from './types';
import { supabase } from './lib/supabaseClient';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const [selectedPlan, setSelectedPlan] = useState<PricingPlan | null>(null);

  useEffect(() => {
    // Listen for Password Recovery event
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'PASSWORD_RECOVERY') {
        setCurrentPage('update-password');
      }
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const handlePlanSelect = (plan: PricingPlan) => {
    setSelectedPlan(plan);
    setCurrentPage('checkout');
    // Scroll to top when moving to checkout
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <Layout currentPage={currentPage} onNavigate={setCurrentPage}>
      {currentPage === 'home' && (
        <>
          <Hero />
          <About />
          <Services />
          <Programs />
          <AICoach />
          <Testimonials />
          <Pricing onSelectPlan={handlePlanSelect} />
          <Contact />
        </>
      )}

      {currentPage === 'login' && <Login onNavigate={setCurrentPage} />}
      {currentPage === 'signup' && <Signup onNavigate={setCurrentPage} />}
      {currentPage === 'forgot-password' && <ForgotPassword onNavigate={setCurrentPage} />}
      {currentPage === 'update-password' && <UpdatePassword onNavigate={setCurrentPage} />}
      {currentPage === 'dashboard' && <Dashboard onNavigate={setCurrentPage} />}
      {currentPage === 'checkout' && selectedPlan && <Checkout plan={selectedPlan} onNavigate={setCurrentPage} />}
      {currentPage === 'admin-login' && <AdminLogin onNavigate={setCurrentPage} />}
      {currentPage === 'admin-dashboard' && <AdminDashboard onNavigate={setCurrentPage} />}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, Eye, EyeOff, ShieldCheck } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface LoginProps {
    onNavigate: (page: string) => void;
}

const Login: React.FC<LoginProps> = ({ onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{email?: string, password?: string}>({});

  const validateForm = () => {
    const errors: {email?: string, password?: string} = {};
    let isValid = true;

    // Email Validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) {
      errors.email = 'Email is required';
      isValid = false;
    } else if (!emailRegex.test(email)) {
      errors.email = 'Please enter a valid email address';
      isValid = false;
    }

    // Password Validation
    if (!password) {
      errors.password = 'Password is required';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');

    if (!validateForm()) return;

    setLoading(true);

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email: email.trim(), 
        password,
      });

      if (error) throw error;

      onNavigate('dashboard');
    } catch (err: any) {
      console.error('Login error:', err);
      if (err.message === 'Invalid login credentials') {
         setGlobalError('Invalid credentials. Please check your password or verify if your email is confirmed.');
      } else if (err.message === 'Failed to fetch') {
         setGlobalError('Network error: Unable to connect. Please check your internet connection or API configuration.');
      } else {
         setGlobalError(err.message || 'Failed to login');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4 relative overflow-hidden">
      {/* Background Ambience */}
      <div className="absolute top-[-20%] left-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-[-20%] right-[-10%] w-[600px] h-[600px] bg-cyan-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md bg-zinc-900 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10"
      >
        <button 
            onClick={() => onNavigate('home')}
            className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors"
        >
            <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="text-center mb-8 mt-4">
            <div className="flex justify-center mb-4">
                <Dumbbell className="w-12 h-12 text-lime-400" />
            </div>
            <h2 className="text-3xl font-heading font-bold text-white mb-2">Welcome Back</h2>
            <p className="text-zinc-400 text-sm">Log in to track your fitness journey.</p>
        </div>

        {globalError && (
            <div className="mb-6 p-3 bg-red-500/10 border border-red-500/50 rounded-lg flex items-start gap-2 text-red-400 text-sm">
                <AlertCircle className="w-4 h-4 mt-0.5 flex-shrink-0" /> 
                <span>{globalError}</span>
            </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Email Address</label>
                <input 
                    type="email" 
                    value={email}
                    onChange={(e) => {
                      setEmail(e.target.value);
                      if (fieldErrors.email) setFieldErrors({...fieldErrors, email: undefined});
                    }}
                    autoComplete="email"
                    className={`w-full bg-zinc-950 border rounded-lg p-3 text-white focus:outline-none focus:ring-1 transition-all ${
                      fieldErrors.email 
