import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, CheckCircle, Mail, Eye, EyeOff } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface SignupProps {
    onNavigate: (page: string) => void;
}

const Signup: React.FC<SignupProps> = ({ onNavigate }) => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [successState, setSuccessState] = useState<'none' | 'confirmation_required' | 'complete'>('none');
  const [passwordStrength, setPasswordStrength] = useState(0);

  const calculateStrength = (pass: string) => {
    let score = 0;
    if (pass.length >= 6) score++;
    if (pass.length >= 10) score++;
    if (/[A-Z]/.test(pass)) score++;
    if (/[0-9]/.test(pass)) score++;
    return score; // Max 4
  };

  const validateForm = () => {
    const errors: Record<string, string> = {};
    let isValid = true;

    if (!formData.firstName.trim() || formData.firstName.length < 2) {
      errors.firstName = 'First name must be at least 2 characters';
      isValid = false;
    }

    if (!formData.lastName.trim() || formData.lastName.length < 2) {
      errors.lastName = 'Last name must be at least 2 characters';
      isValid = false;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      errors.email = 'Please enter a valid email address';
      isValid = false;
    }

    if (formData.password.length < 6) {
      errors.password = 'Password must be at least 6 characters long';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });

    // Clear error when user types
    if (fieldErrors[name]) {
      setFieldErrors(prev => ({ ...prev, [name]: '' }));
    }

    if (name === 'password') {
        setPasswordStrength(calculateStrength(value));
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');

    if (!validateForm()) return;

    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signUp({
        email: formData.email.trim(),
        password: formData.password,
        options: {
          data: {
            first_name: formData.firstName,
            last_name: formData.lastName,
          },
        },
      });

      if (error) throw error;

      if (data?.user && !data?.session) {
        // User created but session is null -> Email confirmation required
        setSuccessState('confirmation_required');
      } else {
        // User created and session exists -> Auto login
        setSuccessState('complete');
        setTimeout(() => {
            onNavigate('home');
        }, 2000);
      }

    } catch (err: any) {
      if (err.message === 'Failed to fetch') {
         setGlobalError('Network error: Unable to connect. Please check your internet connection.');
      } else {
         setGlobalError(err.message || 'Failed to create account');
      }
    } finally {
      setLoading(false);
    }
  };

  if (successState === 'confirmation_required') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-zinc-900 border border-yellow-500/50 p-8 rounded-2xl text-center max-w-md w-full"
            >
                <div className="w-16 h-16 bg-yellow-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Mail className="w-8 h-8 text-yellow-500" />
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">Check Your Email</h2>
                <p className="text-zinc-400 text-sm mb-6 leading-relaxed">
                    We have sent a confirmation link to <span className="text-white font-bold">{formData.email}</span>. 
                    Please verify your email address before logging in.
                </p>
                <button 
                    onClick={() => onNavigate('login')}
                    className="w-full bg-yellow-500 text-black font-bold uppercase py-3 rounded-lg hover:bg-yellow-400 transition-colors"
                >
                    Go to Login
                </button>
            </motion.div>
        </div>
      );
  }

  if (successState === 'complete') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-zinc-900 border border-lime-500 p-8 rounded-2xl text-center max-w-sm w-full"
            >
                <CheckCircle className="w-16 h-16 text-lime-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">Account Created!</h2>
                <p className="text-zinc-400 text-sm mb-4">Redirecting you...</p>
                <Loader2 className="w-5 h-5 animate-spin text-lime-500 mx-auto" />
            </motion.div>
        </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-900 px-4 relative overflow-hidden">
       {/* Background Ambience */}
      <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-[-20%] left-[-10%] w-[600px] h-[600px] bg-cyan-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md bg-zinc-950 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10"
      >
        <button 
            onClick={() => onNavigate('home')}
            className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors"
        >
            <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="text-center mb-8 mt-4">
            <div className="flex justify-center mb-4">
                <Dumbbell className="w-12 h-12 text-cyan-400" />
            </div>
            <h2 className="text-3xl font-heading font-bold text-white mb-2">Join the Hub</h2>
            <p className="text-zinc-400 text-sm">Start your transformation today.</p>
        </div>

        {globalError && (
            <div className="mb-6 p-3 bg-red-500/10 border border-red-500/50 rounded-lg flex items-center gap-2 text-red-400 text-sm">
                <AlertCircle className="w-4 h-4 flex-shrink-0" /> 
                <span>{globalError}</span>
            </div>
        )}

        <form onSubmit={handleSignup} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">First Name</label>
                    <input 
                        name="firstName"
                        type="text" 
                        autoComplete="given-name"
                        value={formData.firstName}
                        onChange={handleChange}
                        className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:outline-none focus:ring-1 transition-all ${
                          fieldErrors.firstName 
                            ? 'border-red-500 focus:border-red-500 focus:ring-red-500' 
                            : 'border-zinc-800 focus:border-cyan-500 focus:ring-cyan-500'
                        }`}
                        placeholder="John"
                    />
                    {fieldErrors.firstName && <p className="text-red-400 text-xs mt-1">{fieldErrors.firstName}</p>}
                </div>
                <div>
                    <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Last Name</label>
                    <input 
                        name="lastName"
                        type="text" 
                        autoComplete="family-name"
                        value={formData.lastName}
                        onChange={handleChange}
                        className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:outline-none focus:ring-1 transition-all ${
                          fieldErrors.lastName 
                            ? 'border-red-500 focus:border-red-500 focus:ring-red-500' 
                            : 'border-zinc-800 focus:border-cyan-500 focus:ring-cyan-500'
                        }`}
                        placeholder="Doe"
                    />
                    {fieldErrors.lastName && <p className="text-red-400 text-xs mt-1">{fieldErrors.lastName}</p>}
                </div>
            </div>

            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Email Address</label>
                <input 
                    name="email"
                    type="email" 
                    autoComplete="email"
                    value={formData.email}
                    onChange={handleChange}
                    className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:outline-none focus:ring-1 transition-all ${
                      fieldErrors.email 
                        ? 'border-red-500 focus:border-red-500 focus:ring-red-500' 
                        : 'border-zinc-800 focus:border-cyan-500 focus:ring-cyan-500'
                    }`}
                    placeholder="you@example.com"
                />
                {fieldErrors.email && <p className="text-red-400 text-xs mt-1">{fieldErrors.email}</p>}
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Password</label>
                <div className="relative">
                    <input 
                        name="password"
                        type={showPassword ? "text" : "password"} 
                        autoComplete="new-password"
                        value={formData.password}
                        onChange={handleChange}
                        className={`w-full bg-zinc-900 border rounded-lg p-3 pr-10 text-white focus:outline-none focus:ring-1 transition-all ${
                          fieldErrors.password 
                            ? 'border-red-500 focus:border-red-500 focus:ring-red-500' 
                            : 'border-zinc-800 focus:border-cyan-500 focus:ring-cyan-500'
                        }`}
                        placeholder="Create a password"
                    />
                    <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="absolute right-3 top-3.5 text-zinc-500 hover:text-white transition-colors"
                        tabIndex={-1}
                    >
                        {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                    </button>
                </div>
                {fieldErrors.password && <p className="text-red-400 text-xs mt-1">{fieldErrors.password}</p>}

                {/* Password Strength Indicator */}
                <div className="mt-3">
                    <div className="flex gap-1 h-1.5">
                        {[1, 2, 3, 4].map((level) => (
                            <div 
                                key={level}
                                className={`flex-1 rounded-full transition-all duration-300 ${
                                    formData.password.length > 0 && passwordStrength >= level 
                                        ? (passwordStrength <= 2 ? 'bg-red-500' : passwordStrength === 3 ? 'bg-yellow-500' : 'bg-lime-500') 
                                        : 'bg-zinc-800'
                                }`}
                            />
                        ))}
                    </div>
                    <div className="flex justify-between items-center mt-1.5">
                        <span className="text-[10px] text-zinc-600 uppercase font-bold tracking-wider">Strength</span>
                        <span className={`text-[10px] font-bold uppercase tracking-wider transition-colors ${
                            passwordStrength === 0 ? 'text-zinc-600' :
                            passwordStrength <= 2 ? 'text-red-500' : 
                            passwordStrength === 3 ? 'text-yellow-500' : 'text-lime-500'
                        }`}>
                            {formData.password.length === 0 ? 'None' : 
                             passwordStrength <= 2 ? 'Weak' : 
                             passwordStrength === 3 ? 'Medium' : 'Strong'}
                        </span>
                    </div>
                </div>
            </div>

            <button 
                type="submit"
                disabled={loading}
                className="w-full bg-gradient-to-r from-lime-500 to-cyan-400 text-black font-bold uppercase py-3 rounded-lg hover:brightness-110 transition-all shadow-[0_0_15px_rgba(34,211,238,0.3)] flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
            >
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Create Account'}
            </button>
        </form>

        <div className="mt-6 text-center text-sm text-zinc-500">
            Already have an account? 
            <button onClick={() => onNavigate('login')} className="text-white font-bold ml-1 hover:text-cyan-400 underline">Login</button>
        </div>
      </motion.div>
    </div>
  );
};

