                        <div className="relative">
                            <input 
                                name="password"
                                type={showPassword ? "text" : "password"}
                                value={formData.password}
                                onChange={handleChange}
                                className={`w-full bg-zinc-900 border rounded-lg p-3 pr-10 text-white focus:outline-none focus:ring-1 transition-all ${fieldErrors.password ? 'border-red-500 focus:border-red-500' : 'border-zinc-800 focus:border-lime-500'}`}
                                placeholder="Min 6 characters"
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-3 top-3.5 text-zinc-500 hover:text-white transition-colors"
                                tabIndex={-1}
                            >
                                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>
                        {fieldErrors.password && <p className="text-red-400 text-xs mt-1">{fieldErrors.password}</p>}

                        {/* Password Strength Indicator */}
                        <div className="mt-3">
                            <div className="flex gap-1 h-1.5">
