import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import { Users, DollarSign, MessageSquare, LogOut, Loader2, Search, Filter, Trash2, Shield, Lock } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface Subscription {
  id: string;
  first_name: string;
  last_name: string;
  email: string;
  membership_plan: string;
  total_paid: number;
  created_at: string;
  subscription_status: string;
}

interface ContactMessage {
  id: string;
  name: string;
  email: string;
  message: string;
  created_at: string;
}

interface AdminDashboardProps {
  onNavigate: (page: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onNavigate }) => {
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'members' | 'messages'>('members');
  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [messages, setMessages] = useState<ContactMessage[]>([]);
  const [stats, setStats] = useState({ revenue: 0, members: 0, leads: 0 });
  const [isAuthorized, setIsAuthorized] = useState(false);

  useEffect(() => {
    checkAuthAndFetch();
  }, []);

  const checkAuthAndFetch = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();

      if (!user) {
        onNavigate('admin-login');
        return;
      }

      // Basic Role Implementation: Check if email indicates admin privileges
      // In a production environment, this should be a check against a 'roles' table or app_metadata
      const isAdmin = user.email?.includes('admin') || user.email?.includes('myfitnesshub');

      if (!isAdmin) {
        // User is logged in but not an admin
        onNavigate('home');
        return;
      }

      setIsAuthorized(true);
      await fetchData();

    } catch (error) {
      console.error('Auth check error:', error);
      onNavigate('admin-login');
    }
  };

  const fetchData = async () => {
    try {
      // 1. Fetch Subscriptions
      const { data: subData, error: subError } = await supabase
        .from('gym_subscriptions')
        .select('*')
        .order('created_at', { ascending: false });

      if (subError) console.error('Error fetching subs:', subError);

      // 2. Fetch Messages
      const { data: msgData, error: msgError } = await supabase
        .from('contact_messages')
        .select('*')
        .order('created_at', { ascending: false });

      if (msgError) console.error('Error fetching messages:', msgError);

      if (subData) setSubscriptions(subData as Subscription[]);
      if (msgData) setMessages(msgData as ContactMessage[]);

      // Calculate Stats
      const totalRevenue = subData?.reduce((acc, curr) => acc + (curr.total_paid || 0), 0) || 0;
      setStats({
        revenue: totalRevenue,
        members: subData?.length || 0,
        leads: msgData?.length || 0
      });

    } catch (error) {
      console.error('Admin Fetch Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    onNavigate('home');
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR' }).format(amount);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
        day: 'numeric', month: 'short', year: 'numeric'
    });
  };

  if (loading || !isAuthorized) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-950 flex-col gap-4">
        <Loader2 className="w-10 h-10 text-red-500 animate-spin" />
        <p className="text-zinc-500 text-sm animate-pulse">Verifying Access...</p>
      </div>
    );
  }

  return (
