                    >
                        <LogOut className="w-3 h-3" /> Logout
                    </button>
                </div>
            </div>
        </div>

        <div className="container mx-auto p-4 md:p-8">

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <motion.div 
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-zinc-900 p-6 rounded-xl border border-zinc-800"
                >
                    <div className="flex justify-between items-start mb-4">
                        <div>
                            <p className="text-zinc-400 text-xs font-bold uppercase">Total Revenue</p>
                            <h3 className="text-2xl font-bold text-white mt-1">{formatCurrency(stats.revenue)}</h3>
                        </div>
                        <div className="p-3 bg-lime-500/10 rounded-lg">
                            <DollarSign className="w-6 h-6 text-lime-400" />
                        </div>
                    </div>
                </motion.div>

                <motion.div 
                    initial={{ opacity: 0, y: 20 }}
