import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, CheckCircle, Mail, Eye, EyeOff } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface SignupProps {
    onNavigate: (page: string) => void;
}

const Signup: React.FC<SignupProps> = ({ onNavigate }) => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [successState, setSuccessState] = useState<'none' | 'confirmation_required' | 'complete'>('none');
  const [passwordStrength, setPasswordStrength] = useState(0);

  const calculateStrength = (pass: string) => {
    let score = 0;
    if (pass.length >= 6) score++;
    if (pass.length >= 10) score++;
    if (/[A-Z]/.test(pass)) score++;
    if (/[0-9]/.test(pass)) score++;
    return score;
  };

  const validateForm = () => {
    const errors: Record<string, string> = {};
    let isValid = true;

    if (!formData.firstName.trim() || formData.firstName.length < 2) {
      errors.firstName = 'First name required';
      isValid = false;
    }

    if (!formData.lastName.trim() || formData.lastName.length < 2) {
      errors.lastName = 'Last name required';
      isValid = false;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      errors.email = 'Valid email required';
      isValid = false;
    }

    if (formData.password.length < 6) {
      errors.password = 'Min 6 characters';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
    if (fieldErrors[name]) setFieldErrors(prev => ({ ...prev, [name]: '' }));
    if (name === 'password') setPasswordStrength(calculateStrength(value));
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');

    if (!validateForm()) return;

    setLoading(true);

    try {
      // 1. Supabase Auth Signup
      const { data, error } = await supabase.auth.signUp({
        email: formData.email.trim(),
        password: formData.password,
        options: {
          data: {
            first_name: formData.firstName,
            last_name: formData.lastName,
          },
        },
      });

      if (error) throw error;

      // 2. Insert into public.profiles table (LOGIN DETAILS COLLECTION)
      if (data?.user) {
          const { error: profileError } = await supabase.from('profiles').insert([
              {
                  id: data.user.id,
                  email: formData.email.trim(),
                  first_name: formData.firstName,
                  last_name: formData.lastName
              }
          ]);
          if (profileError) console.error("Profile creation error:", profileError);
      }

      if (data?.user && !data?.session) {
        setSuccessState('confirmation_required');
      } else {
        setSuccessState('complete');
        setTimeout(() => onNavigate('home'), 2000);
      }

    } catch (err: any) {
      setGlobalError(err.message || 'Failed to create account');
    } finally {
      setLoading(false);
    }
  };

  if (successState === 'confirmation_required') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="bg-zinc-900 border border-yellow-500/50 p-8 rounded-2xl text-center max-w-md w-full">
                <Mail className="w-16 h-16 text-yellow-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">Check Your Email</h2>
                <p className="text-zinc-400 text-sm mb-6 leading-relaxed">Confirmation link sent to <span className="text-white font-bold">{formData.email}</span>. Please verify before logging in.</p>
                <button onClick={() => onNavigate('login')} className="w-full bg-yellow-500 text-black font-bold uppercase py-3 rounded-lg hover:bg-yellow-400 transition-colors">Go to Login</button>
            </motion.div>
        </div>
      );
  }

  if (successState === 'complete') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="bg-zinc-900 border border-lime-500 p-8 rounded-2xl text-center max-w-sm w-full">
                <CheckCircle className="w-16 h-16 text-lime-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">Account Created!</h2>
                <p className="text-zinc-400 text-sm mb-4">Redirecting you...</p>
                <Loader2 className="w-5 h-5 animate-spin text-lime-500 mx-auto" />
            </motion.div>
        </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-900 px-4 relative overflow-hidden">
      <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md bg-zinc-950 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10">
        <button onClick={() => onNavigate('home')} className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors"><ArrowLeft className="w-6 h-6" /></button>
        <div className="text-center mb-8 mt-4">
            <Dumbbell className="w-12 h-12 text-cyan-400 mx-auto mb-4" />
            <h2 className="text-3xl font-heading font-bold text-white mb-2">Join the Hub</h2>
            <p className="text-zinc-400 text-sm">Create your login credentials.</p>
        </div>
        {globalError && <div className="mb-6 p-3 bg-red-500/10 border border-red-500/50 rounded-lg flex items-center gap-2 text-red-400 text-sm"><AlertCircle className="w-4 h-4 flex-shrink-0" /><span>{globalError}</span></div>}
        <form onSubmit={handleSignup} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">First Name</label>
                    <input name="firstName" type="text" value={formData.firstName} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.firstName ? 'border-red-500' : 'border-zinc-800'}`} placeholder="John" />
                </div>
                <div>
                    <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Last Name</label>
                    <input name="lastName" type="text" value={formData.lastName} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.lastName ? 'border-red-500' : 'border-zinc-800'}`} placeholder="Doe" />
                </div>
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Email Address</label>
                <input name="email" type="email" value={formData.email} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.email ? 'border-red-500' : 'border-zinc-800'}`} placeholder="you@example.com" />
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Password</label>
                <div className="relative">
                    <input name="password" type={showPassword ? "text" : "password"} value={formData.password} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 pr-10 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.password ? 'border-red-500' : 'border-zinc-800'}`} placeholder="Create password" />
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3.5 text-zinc-500 hover:text-white">{showPassword ? <EyeOff size={20} /> : <Eye size={20} />}</button>
                </div>
            </div>
            <button type="submit" disabled={loading} className="w-full bg-gradient-to-r from-lime-500 to-cyan-400 text-black font-bold uppercase py-3 rounded-lg hover:brightness-110 shadow-lg disabled:opacity-70 flex items-center justify-center gap-2">{loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Create Account'}</button>
        </form>
        <div className="mt-6 text-center text-sm text-zinc-500">Already have an account? <button onClick={() => onNavigate('login')} className="text-white font-bold hover:text-cyan-400 underline">Login</button></div>
      </motion.div>
    </div>
  );
};

