import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, Eye, EyeOff, ShieldCheck, Mail } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface LoginProps {
    onNavigate: (page: string) => void;
}

const Login: React.FC<LoginProps> = ({ onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{email?: string, password?: string}>({});

  const validateForm = () => {
    const errors: {email?: string, password?: string} = {};
    let isValid = true;

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) {
      errors.email = 'Email is required';
      isValid = false;
    } else if (!emailRegex.test(email)) {
      errors.email = 'Please enter a valid email address';
      isValid = false;
    }

    if (!password) {
      errors.password = 'Password is required';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');

    if (!validateForm()) return;

    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(), 
        password,
      });

      if (error) throw error;

      // Check if this is an admin login attempt via standard login
      const isAdmin = email.includes('admin') || email.includes('myfitnesshub');
      if (isAdmin) {
          onNavigate('admin-dashboard');
      } else {
          onNavigate('dashboard');
      }

    } catch (err: any) {
      console.error('Login error:', err);
      // Supabase returns "Invalid login credentials" for both wrong password AND unconfirmed email
      if (err.message === 'Invalid login credentials') {
         setGlobalError('Invalid credentials. If you just signed up, please check your inbox to confirm your email address before logging in.');
      } else if (err.message === 'Failed to fetch') {
         setGlobalError('Connection error. Please check your internet connection.');
      } else {
         setGlobalError(err.message || 'An unexpected error occurred.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4 relative overflow-hidden">
      <div className="absolute top-[-20%] left-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-[-20%] right-[-10%] w-[600px] h-[600px] bg-cyan-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md bg-zinc-900 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10"
      >
        <button 
            onClick={() => onNavigate('home')}
            className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors"
        >
            <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="text-center mb-8 mt-4">
            <div className="flex justify-center mb-4">
                <Dumbbell className="w-12 h-12 text-lime-400" />
            </div>
            <h2 className="text-3xl font-heading font-bold text-white mb-2">Welcome Back</h2>
            <p className="text-zinc-400 text-sm">Log in to track your fitness journey.</p>
        </div>

        {globalError && (
            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/50 rounded-lg flex items-start gap-3 text-red-400 text-sm leading-relaxed">
                <AlertCircle className="w-5 h-5 mt-0.5 flex-shrink-0" /> 
                <span>{globalError}</span>
            </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Email Address</label>
                <div className="relative">
                    <Mail className="absolute left-3 top-3.5 w-5 h-5 text-zinc-600" />
                    <input 
                        type="email" 
                        value={email}
                        onChange={(e) => {
                          setEmail(e.target.value);
                          if (fieldErrors.email) setFieldErrors({...fieldErrors, email: undefined});
                        }}
                        autoComplete="email"
                        className={`w-full bg-zinc-950 border rounded-lg p-3 pl-10 text-white focus:outline-none focus:ring-1 transition-all ${
                          fieldErrors.email 
                            ? 'border-red-500 focus:border-red-500 focus:ring-red-500' 
                            : 'border-zinc-800 focus:border-lime-500 focus:ring-lime-500'
                        }`}
                        placeholder="you@example.com"
