import { supabase } from '../lib/supabaseClient';

interface LoginProps {
    onNavigate: (page: string) => void;
}

const Login: React.FC<LoginProps> = ({ onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{email?: string, password?: string}>({});

  const validateForm = () => {
    const errors: {email?: string, password?: string} = {};
    let isValid = true;

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) {
      errors.email = 'Email is required';
      isValid = false;
    } else if (!emailRegex.test(email)) {
      errors.email = 'Please enter a valid email address';
      isValid = false;
    }

    if (!password) {
      errors.password = 'Password is required';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');

    if (!validateForm()) return;

    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(), 
        password,
      });

      if (error) throw error;

      // Check if this is an admin login attempt
      const isAdmin = email.toLowerCase().includes('admin') || email.toLowerCase().includes('myfitnesshub');
      if (isAdmin) {
          onNavigate('admin-dashboard');
      } else {
          onNavigate('dashboard');
      }

    } catch (err: any) {
      console.error('Login error:', err);
      // Supabase returns "Invalid login credentials" for both wrong password AND unconfirmed email
      if (err.message.includes('Invalid login credentials')) {
         setGlobalError('The credentials provided are incorrect. If you recently signed up, please ensure you have confirmed your email via the link we sent to your inbox.');
      } else if (err.message === 'Failed to fetch') {
         setGlobalError('Connection lost. Please check your internet and try again.');
      } else {
         setGlobalError(err.message || 'An unexpected error occurred during login.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4 relative overflow-hidden">
