                    <Mail className="w-10 h-10 text-yellow-500" />
                </div>
                <h2 className="text-3xl font-heading font-bold text-white mb-4">Verify Your Email</h2>
                <p className="text-zinc-400 text-sm mb-8 leading-relaxed">
                    We've sent a verification link to <span className="text-white font-bold">{formData.email}</span>.<br/><br/>
                    You <span className="text-yellow-500 font-bold uppercase">must</span> click this link before you can log in.
                </p>
                <div className="space-y-4">
                    <button onClick={() => onNavigate('login')} className="w-full bg-yellow-500 text-black font-bold uppercase py-4 rounded-xl hover:bg-yellow-400 transition-colors tracking-widest">
                        Back to Login
                    </button>
                    <p className="text-[10px] text-zinc-500 uppercase font-bold tracking-widest">Didn't get the email? Check your spam folder.</p>
                </div>
            </motion.div>
        </div>
      );
  }

  if (successState === 'complete') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="bg-zinc-900 border border-lime-500 p-8 rounded-2xl text-center max-w-sm w-full">
                <CheckCircle className="w-16 h-16 text-lime-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">Account Created!</h2>
                <p className="text-zinc-400 text-sm mb-4">You are now part of the hub. Redirecting...</p>
                <Loader2 className="w-5 h-5 animate-spin text-lime-500 mx-auto" />
            </motion.div>
        </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-900 px-4 relative overflow-hidden">
      <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md bg-zinc-950 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10">
        <button onClick={() => onNavigate('home')} className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors"><ArrowLeft className="w-6 h-6" /></button>

        <div className="text-center mb-8 mt-4">
            <Dumbbell className="w-12 h-12 text-cyan-400 mx-auto mb-4" />
            <h2 className="text-3xl font-heading font-bold text-white mb-2">Join the Hub</h2>
            <p className="text-zinc-400 text-sm uppercase tracking-widest font-bold">Start Your Journey Today</p>
        </div>

        {globalError && (
            <div className={`mb-6 p-4 rounded-lg flex items-start gap-3 text-sm ${isAlreadyRegistered ? 'bg-cyan-500/10 border border-cyan-500/50 text-cyan-400' : 'bg-red-500/10 border border-red-500/50 text-red-400'}`}>
                <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
                <div className="flex-1">
                    <p className="font-bold mb-2">{globalError}</p>
                    {isAlreadyRegistered && (
                        <button 
                            onClick={() => onNavigate('login')}
                            className="flex items-center gap-2 bg-cyan-500 text-black px-4 py-2 rounded font-bold uppercase text-xs hover:bg-white transition-colors"
                        >
                            <LogIn className="w-3 h-3" /> Login Instead
                        </button>
                    )}
                </div>
            </div>
        )}

        <form onSubmit={handleSignup} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">First Name</label>
                    <input name="firstName" type="text" value={formData.firstName} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.firstName ? 'border-red-500' : 'border-zinc-800'}`} placeholder="John" />
                    {fieldErrors.firstName && <p className="text-red-400 text-[10px] mt-1 font-bold">{fieldErrors.firstName}</p>}
                </div>
                <div>
                    <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Last Name</label>
                    <input name="lastName" type="text" value={formData.lastName} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.lastName ? 'border-red-500' : 'border-zinc-800'}`} placeholder="Doe" />
                    {fieldErrors.lastName && <p className="text-red-400 text-[10px] mt-1 font-bold">{fieldErrors.lastName}</p>}
                </div>
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Email Address</label>
                <div className="relative">
                    <Mail className="absolute left-3 top-3.5 w-4 h-4 text-zinc-600" />
                    <input name="email" type="email" value={formData.email} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 pl-10 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.email || isAlreadyRegistered ? 'border-red-500' : 'border-zinc-800'}`} placeholder="you@example.com" />
                </div>
                {fieldErrors.email && <p className="text-red-400 text-[10px] mt-1 font-bold">{fieldErrors.email}</p>}
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Password</label>
                <div className="relative">
                    <input name="password" type={showPassword ? "text" : "password"} value={formData.password} onChange={handleChange} className={`w-full bg-zinc-900 border rounded-lg p-3 pr-10 text-white focus:border-cyan-500 outline-none transition-all ${fieldErrors.password ? 'border-red-500' : 'border-zinc-800'}`} placeholder="Min 6 characters" />
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3.5 text-zinc-500 hover:text-white transition-colors">{showPassword ? <EyeOff size={18} /> : <Eye size={18} />}</button>
                </div>
                {fieldErrors.password && <p className="text-red-400 text-[10px] mt-1 font-bold">{fieldErrors.password}</p>}
            </div>

            <div className="pt-2">
                <button type="submit" disabled={loading} className="w-full bg-gradient-to-r from-lime-500 to-cyan-400 text-black font-bold uppercase py-4 rounded-xl hover:brightness-110 shadow-lg disabled:opacity-70 flex items-center justify-center gap-2 tracking-widest">
                    {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Create Account'}
                </button>
            </div>
        </form>

        <div className="mt-8 text-center text-sm text-zinc-500">
            Already have an account? <button onClick={() => onNavigate('login')} className="text-white font-bold hover:text-cyan-400 underline">Login Instead</button>
        </div>

        <div className="mt-8 pt-6 border-t border-zinc-800 flex items-center justify-center gap-2 text-zinc-600">
            <ShieldCheck className="w-4 h-4" />
            <span className="text-[10px] font-bold uppercase tracking-widest">Secure Registration</span>
        </div>
      </motion.div>
    </div>
  );
};

export default Signup;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Users, 
  DollarSign, 
  MessageSquare, 
  LogOut, 
  Loader2, 
  Search, 
  Shield, 
  UserCircle, 
  ExternalLink, 
  Calendar, 
  MapPin, 
  Phone, 
  Mail, 
  Clock,
  ChevronRight,
  X,
  CreditCard,
  Target
} from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface Subscription {
  id: string;
  first_name: string;
  last_name: string;
  email: string;
  phone_number: string;
  membership_plan: string;
  total_paid: number;
  street_address: string;
  city: string;
  zip_code: string;
  created_at: string;
  subscription_status: string;
}

interface UserProfile {
  id: string;
  email: string;
  first_name: string;
  last_name: string;
  created_at: string;
}

interface ContactMessage {
  id: string;
  name: string;
  email: string;
  phone: string;
  message: string;
  created_at: string;
}

interface AdminDashboardProps {
  onNavigate: (page: string) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ onNavigate }) => {
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'members' | 'users' | 'messages'>('members');
  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [messages, setMessages] = useState<ContactMessage[]>([]);
  const [stats, setStats] = useState({ revenue: 0, members: 0, users: 0, leads: 0 });
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedItem, setSelectedItem] = useState<any>(null);

  useEffect(() => {
    checkAuthAndFetch();
  }, []);

  const checkAuthAndFetch = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        onNavigate('admin-login');
        return;
      }
      const isAdmin = user.email?.toLowerCase().includes('admin') || user.email?.toLowerCase().includes('myfitnesshub');
      if (!isAdmin) {
        onNavigate('home');
        return;
      }
      setIsAuthorized(true);
      await fetchData();
    } catch (error) {
      console.error('Auth check error:', error);
      onNavigate('admin-login');
    }
  };

  const fetchData = async () => {
    try {
      setLoading(true);
      const { data: subData } = await supabase.from('gym_subscriptions').select('*').order('created_at', { ascending: false });
      const { data: profileData } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      const { data: msgData } = await supabase.from('contact_messages').select('*').order('created_at', { ascending: false });

      if (subData) setSubscriptions(subData as Subscription[]);
      if (profileData) setUsers(profileData as UserProfile[]);
      if (msgData) setMessages(msgData as ContactMessage[]);

      const totalRevenue = subData?.reduce((acc, curr) => acc + (curr.total_paid || 0), 0) || 0;
      setStats({
        revenue: totalRevenue,
        members: subData?.length || 0,
        users: profileData?.length || 0,
        leads: msgData?.length || 0
      });
    } catch (error) {
      console.error('Admin Fetch Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    onNavigate('home');
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(amount);
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-IN', {
        day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
    });
  };

  if (loading || !isAuthorized) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-950 flex-col gap-4">
        <Loader2 className="w-10 h-10 text-red-500 animate-spin" />
        <p className="text-zinc-500 text-sm font-bold uppercase tracking-widest animate-pulse">Establishing Secure Uplink...</p>
      </div>
    );
  }

  return (
    <section className="min-h-screen bg-zinc-950 text-white selection:bg-red-500/30">
        {/* Header */}
        <div className="bg-zinc-900/50 backdrop-blur-md border-b border-zinc-800 p-4 sticky top-0 z-40">
            <div className="container mx-auto flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-red-500/10 rounded-lg flex items-center justify-center border border-red-500/20">
                        <Shield className="w-6 h-6 text-red-500" />
                    </div>
                    <h1 className="text-xl font-heading font-bold tracking-tight">HUB<span className="text-red-500"> COMMAND</span></h1>
                </div>
                <div className="flex items-center gap-6">
                    <div className="hidden md:flex flex-col items-end">
                        <span className="text-[10px] text-zinc-500 uppercase font-bold tracking-widest">System Status</span>
                        <span className="text-[10px] text-lime-500 font-bold flex items-center gap-1"><div className="w-1.5 h-1.5 bg-lime-500 rounded-full animate-pulse"></div> OPERATIONAL</span>
                    </div>
                    <button 
                        onClick={handleLogout}
                        className="flex items-center gap-2 bg-zinc-800 hover:bg-red-600 px-4 py-2 rounded-lg text-xs font-bold uppercase transition-all duration-300 shadow-lg"
                    >
                        <LogOut className="w-3.5 h-3.5" /> Logout
                    </button>
                </div>
            </div>
        </div>

        <div className="container mx-auto p-4 md:p-8">
            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-10">
                {[
                    { label: 'Total Revenue', value: formatCurrency(stats.revenue), icon: DollarSign, color: 'text-lime-400', bg: 'bg-lime-500/5' },
                    { label: 'Subscribed Members', value: stats.members, icon: Users, color: 'text-red-500', bg: 'bg-red-500/5' },
                    { label: 'Registered Logins', value: stats.users, icon: UserCircle, color: 'text-cyan-400', bg: 'bg-cyan-500/5' },
                    { label: 'Contact Leads', value: stats.leads, icon: MessageSquare, color: 'text-purple-400', bg: 'bg-purple-500/5' }
                ].map((stat, i) => (
                    <motion.div 
                        key={i}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: i * 0.1 }}
                        className={`p-6 rounded-2xl border border-zinc-800 ${stat.bg} relative overflow-hidden group`}
                    >
                        <div className="relative z-10">
                            <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-widest mb-1">{stat.label}</p>
                            <h3 className={`text-3xl font-bold ${stat.color}`}>{stat.value}</h3>
                        </div>
                        <stat.icon size={80} className={`absolute -right-4 -bottom-4 opacity-5 group-hover:scale-110 group-hover:opacity-10 transition-all duration-500 ${stat.color}`} />
                    </motion.div>
                ))}
            </div>

            {/* Controls */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-6 bg-zinc-900/30 p-4 rounded-2xl border border-zinc-800">
