                                    <tr>
                                        <th className="p-5">Lead Name</th>
                                        <th className="p-5">Contact Details</th>
                                        <th className="p-5">Snippet</th>
                                        <th className="p-5">Received</th>
                                        <th className="p-5 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-zinc-800">
