import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, CheckCircle, Mail, Eye, EyeOff, ShieldCheck, LogIn, Shield } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface SignupProps {
    onNavigate: (page: string) => void;
}

const Signup: React.FC<SignupProps> = ({ onNavigate }) => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [isAlreadyRegistered, setIsAlreadyRegistered] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [successState, setSuccessState] = useState<'none' | 'confirmation_required' | 'complete'>('none');
  const [passwordStrength, setPasswordStrength] = useState(0);

  const calculateStrength = (pass: string) => {
    let score = 0;
    if (pass.length >= 6) score++;
    if (pass.length >= 10) score++;
    if (/[A-Z]/.test(pass)) score++;
    if (/[0-9]/.test(pass)) score++;
    return score; // Max 4
  };

  const validateForm = () => {
    const errors: Record<string, string> = {};
    let isValid = true;

    if (!formData.firstName.trim() || formData.firstName.length < 2) {
      errors.firstName = 'First name required';
      isValid = false;
    }
    if (!formData.lastName.trim() || formData.lastName.length < 2) {
      errors.lastName = 'Last name required';
      isValid = false;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      errors.email = 'Valid email required';
      isValid = false;
    }
    if (formData.password.length < 6) {
      errors.password = 'Min 6 characters';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
    if (fieldErrors[name]) setFieldErrors(prev => ({ ...prev, [name]: '' }));
    if (globalError) setGlobalError('');
    if (isAlreadyRegistered) setIsAlreadyRegistered(false);

    if (name === 'password') {
      setPasswordStrength(calculateStrength(value));
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');
    setIsAlreadyRegistered(false);

    if (!validateForm()) return;

    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signUp({
        email: formData.email.trim(),
        password: formData.password,
        options: {
          data: {
            first_name: formData.firstName,
            last_name: formData.lastName,
          },
        },
      });

      if (error) {
        if (error.message.toLowerCase().includes('already registered')) {
            setIsAlreadyRegistered(true);
            throw new Error('An account with this email already exists.');
        }
        throw error;
      }

      if (data?.user && !data?.session) {
        setSuccessState('confirmation_required');
      } else {
        setSuccessState('complete');
        setTimeout(() => onNavigate('home'), 2000);
      }

    } catch (err: any) {
      console.error('Signup error:', err);
      setGlobalError(err.message || 'Failed to create account. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  if (successState === 'confirmation_required') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0 }} 
                animate={{ scale: 1, opacity: 1 }} 
                className="bg-zinc-900 border border-yellow-500/30 p-10 rounded-3xl text-center max-w-md w-full shadow-2xl shadow-yellow-500/5"
            >
                <div className="w-20 h-20 bg-yellow-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
                    <Mail className="w-10 h-10 text-yellow-500" />
                </div>
                <h2 className="text-3xl font-heading font-bold text-white mb-4">Verify Your Email</h2>
                <p className="text-zinc-400 text-sm mb-8 leading-relaxed">
                    We've sent a verification link to <span className="text-white font-bold">{formData.email}</span>.<br/><br/>
                    You <span className="text-yellow-500 font-bold uppercase">must</span> click this link before you can log in.
                </p>
                <div className="space-y-4">
                    <button onClick={() => onNavigate('login')} className="w-full bg-yellow-500 text-black font-bold uppercase py-4 rounded-xl hover:bg-yellow-400 transition-colors tracking-widest">
                        Back to Login
                    </button>
                    <p className="text-[10px] text-zinc-500 uppercase font-bold tracking-widest">Didn't get the email? Check your spam folder.</p>
                </div>
            </motion.div>
        </div>
      );
  }

  if (successState === 'complete') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4">
            <motion.div initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="bg-zinc-900 border border-lime-500 p-8 rounded-2xl text-center max-w-sm w-full">
                <CheckCircle className="w-16 h-16 text-lime-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">Account Created!</h2>
                <p className="text-zinc-400 text-sm mb-4">You are now part of the hub. Redirecting...</p>
                <Loader2 className="w-5 h-5 animate-spin text-lime-500 mx-auto" />
            </motion.div>
        </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-900 px-4 relative overflow-hidden">
      <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="w-full max-w-md bg-zinc-950 border border-zinc-800 p-8 rounded-2xl shadow-2xl relative z-10">
