                    { label: 'Subscribed Members', value: stats.members, icon: Users, color: 'text-red-500', bg: 'bg-red-500/5' },
                    { label: 'Registered Logins', value: stats.users, icon: UserCircle, color: 'text-cyan-400', bg: 'bg-cyan-500/5' },
