                    className="w-full bg-zinc-950 border border-zinc-800 rounded-lg p-3 text-white focus:outline-none focus:border-red-500 transition-all"
                    placeholder="admin@myfitnesshub.fit"
                />
            </div>
            <div>
                <label className="block text-zinc-400 text-xs font-bold uppercase mb-2">Password</label>
                <div className="relative">
                    <input 
                        type={showPassword ? "text" : "password"}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                        className="w-full bg-zinc-950 border border-zinc-800 rounded-lg p-3 pr-10 text-white focus:outline-none focus:border-red-500 transition-all"
                        placeholder="••••••••"
                    />
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3.5 text-zinc-500 hover:text-white transition-colors">
                        {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                    </button>
                </div>
            </div>

            <button type="submit" disabled={loading} className="w-full bg-red-600 text-white font-bold uppercase py-4 rounded-lg hover:bg-red-500 transition-colors shadow-[0_0_15px_rgba(220,38,38,0.3)] flex items-center justify-center gap-2 mt-6">
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <><Lock className="w-4 h-4" /> Authenticate</>}
            </button>
        </form>
      </motion.div>
    </div>
  );
};

export default AdminLogin;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { GoogleGenAI } from "@google/genai";
import { Bot, Sparkles, Send, Loader2, Save, CheckCircle, Flame, Dumbbell, History } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

const AICoach: React.FC = () => {
  const [goal, setGoal] = useState('');
  const [level, setLevel] = useState('Beginner');
  const [response, setResponse] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [user, setUser] = useState<any>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });
  }, []);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!goal) return;

    setLoading(true);
    setResponse('');
    setSaveSuccess(false);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        You are 'Fitness Hub AI', an elite fitness coach. 
        Goal: "${goal}".
        Level: "${level}".

        Create a high-intensity, professional daily workout. 
        Format your response CLEARLY with the following structure:
        ### [Workout Name]
        **Focus:** [Goal]
        ---
        #### Phase 1: Warmup
        * Exercise 1 (Sets x Reps)
        #### Phase 2: Main Session
        * Exercise 2 (Sets x Reps)
        #### Phase 3: Cool Down
        * Exercise 3
        ---
        **Coach's Tip:** [Intense motivational tip]
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setResponse(result.text || "Could not generate plan.");
    } catch (error) {
      console.error("AI Error:", error);
      setResponse("System overload. Please check your connection.");
    } finally {
      setLoading(false);
    }
  };

  const saveWorkout = async () => {
    if (!user || !response) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from('user_workouts')
        .insert([{
          user_id: user.id,
          goal: goal,
          plan_content: response,
          level: level,
          created_at: new Date().toISOString()
        }]);

      if (error) throw error;
      setSaveSuccess(true);
    } catch (err) {
      console.error("Save error:", err);
    } finally {
      setSaving(false);
    }
  };

  return (
    <section id="ai-coach" className="py-24 bg-zinc-950 border-y border-zinc-900 relative overflow-hidden">
      {/* Dynamic Background */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-lime-500/5 blur-[120px] rounded-full animate-pulse"></div>
        <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-cyan-500/5 blur-[120px] rounded-full animate-pulse delay-700"></div>
      </div>

      <div className="container mx-auto px-4 relative z-10">
        <div className="text-center mb-16">
            <motion.div 
                initial={{ opacity: 0, scale: 0.9 }}
                whileInView={{ opacity: 1, scale: 1 }}
                className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-zinc-900 border border-zinc-800 mb-6 shadow-xl"
            >
                <Sparkles className="w-4 h-4 text-lime-400" />
                <span className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em]">Neural Coaching Engine</span>
            </motion.div>
            <h2 className="text-5xl md:text-7xl font-heading font-bold text-white mb-6 tracking-tighter">
                AI <span className="text-transparent bg-clip-text bg-gradient-to-r from-lime-400 to-cyan-400">COMMANDER</span>
            </h2>
            <p className="text-zinc-500 max-w-2xl mx-auto text-lg">
                Input your objective. Our elite backend neural net will architect a battle-plan tailored to your current capacity.
            </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 items-start max-w-7xl mx-auto">
            {/* Control Deck */}
            <motion.div 
                initial={{ opacity: 0, x: -40 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                className="bg-zinc-900/40 backdrop-blur-xl p-10 border border-zinc-800 rounded-3xl relative overflow-hidden shadow-2xl"
            >
                <div className="absolute top-0 right-0 p-4">
                    <History className="w-10 h-10 text-zinc-800 opacity-20" />
                </div>

                <form onSubmit={handleGenerate} className="relative z-10 space-y-8">
                    <div>
                        <label className="block text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em] mb-4">Tactical Objective</label>
                        <div className="relative">
                            <input 
                                type="text" 
                                value={goal}
                                onChange={(e) => setGoal(e.target.value)}
                                placeholder="Build chest mass, Explosive power..."
                                className="w-full bg-zinc-950 border border-zinc-800 p-5 text-white placeholder-zinc-700 focus:outline-none focus:border-lime-500 transition-all rounded-2xl text-lg shadow-inner"
                            />
                            <Flame className="absolute right-5 top-1/2 -translate-y-1/2 text-zinc-800 w-6 h-6" />
                        </div>
                    </div>

                    <div>
                        <label className="block text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em] mb-4">Clearance Level</label>
                        <div className="grid grid-cols-3 gap-3">
                            {['Beginner', 'Intermediate', 'Advanced'].map((lvl) => (
                                <button
                                    key={lvl}
                                    type="button"
                                    onClick={() => setLevel(lvl)}
                                    className={`py-4 text-xs font-black uppercase rounded-xl border-2 transition-all ${
                                        level === lvl 
                                        ? 'bg-lime-500 text-black border-lime-500 shadow-lg shadow-lime-500/20 scale-105' 
                                        : 'bg-zinc-950 text-zinc-600 border-zinc-800 hover:border-zinc-700'
                                    }`}
                                >
                                    {lvl}
                                </button>
                            ))}
                        </div>
                    </div>

                    <button 
                        type="submit" 
                        disabled={loading || !goal}
                        className="w-full py-5 bg-white text-black font-black uppercase tracking-[0.3em] hover:bg-lime-500 transition-all rounded-2xl disabled:opacity-30 flex items-center justify-center gap-3 shadow-2xl group"
                    >
                        {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Dumbbell className="w-6 h-6 group-hover:rotate-45 transition-transform" />}
                        {loading ? 'ARCHITECTING...' : 'INITIATE PLAN'}
                    </button>
                </form>
            </motion.div>

            {/* Tactical Output */}
            <motion.div 
                initial={{ opacity: 0, x: 40 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                className="min-h-[550px] bg-zinc-950 border border-zinc-800 rounded-3xl p-1 relative overflow-hidden shadow-2xl"
            >
                 <div className="absolute inset-0 bg-zinc-900/50"></div>

                 <div className="relative z-10 h-full flex flex-col p-10">
                    <AnimatePresence mode="wait">
                        {response ? (
                            <motion.div 
                                key="output"
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="flex-1"
                            >
                                <div className="flex items-center justify-between mb-8 pb-6 border-b border-zinc-800">
                                     <div className="flex items-center gap-4">
                                        <div className="w-12 h-12 rounded-2xl bg-cyan-500/10 flex items-center justify-center text-cyan-400 border border-cyan-500/20">
                                            <Bot className="w-7 h-7" />
                                        </div>
                                        <div>
                                            <h4 className="text-white font-heading font-bold text-xl uppercase tracking-tight">Mission Brief</h4>
                                            <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Optimized for: {level}</p>
                                        </div>
                                     </div>

                                     {user && (
                                         <button 
                                            onClick={saveWorkout}
                                            disabled={saving || saveSuccess}
                                            className={`p-3 rounded-xl border transition-all flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest ${
                                                saveSuccess 
                                                ? 'bg-lime-500/10 border-lime-500 text-lime-400' 
                                                : 'bg-zinc-900 border-zinc-800 text-zinc-400 hover:text-white hover:border-zinc-700'
                                            }`}
                                         >
                                            {saving ? <Loader2 className="w-3 h-3 animate-spin" /> : saveSuccess ? <CheckCircle className="w-3 h-3" /> : <Save className="w-3 h-3" />}
                                            {saveSuccess ? 'Stored' : 'Save to Profile'}
                                         </button>
                                     )}
                                </div>
                                <div className="space-y-4 text-zinc-300 font-medium leading-relaxed max-h-[400px] overflow-y-auto pr-4 custom-scrollbar">
                                    {response.split('\n').map((line, i) => {
                                        if (line.startsWith('###')) return <h3 key={i} className="text-2xl font-heading text-lime-400 mt-6 mb-2">{line.replace('###', '')}</h3>;
                                        if (line.startsWith('####')) return <h4 key={i} className="text-lg font-heading text-cyan-400 mt-4 mb-1 uppercase">{line.replace('####', '')}</h4>;
                                        if (line.startsWith('**Coach\'s Tip:**')) return <div key={i} className="bg-zinc-900 p-4 rounded-xl border-l-4 border-lime-500 my-6 italic text-sm text-zinc-400">{line}</div>;
                                        if (line.includes('---')) return <hr key={i} className="border-zinc-800 my-4" />;
                                        return <p key={i} className="mb-1 text-sm">{line}</p>;
                                    })}
                                </div>
                            </motion.div>
                        ) : (
                            <motion.div 
                                key="placeholder"
                                initial={{ opacity: 0 }}
                                animate={{ opacity: 1 }}
                                className="flex-1 flex flex-col items-center justify-center text-zinc-800"
                            >
                                <Bot className="w-24 h-24 mb-6 opacity-10 animate-pulse" />
                                <p className="text-center max-w-xs text-[10px] font-black uppercase tracking-[0.3em] opacity-40">
                                    System Standby. <br/>
                                    Input parameters to compile routine.
                                </p>
                            </motion.div>
                        )}
                    </AnimatePresence>
                 </div>

                 {/* Cyberpunk Accents */}
                 <div className="absolute top-0 right-0 w-24 h-24 border-t border-r border-lime-500/20 rounded-tr-3xl"></div>
                 <div className="absolute bottom-0 left-0 w-24 h-24 border-b border-l border-cyan-500/20 rounded-bl-3xl"></div>
            </motion.div>
        </div>
      </div>
    </section>
  );
};

export default AICoach;

import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { User, CreditCard, Calendar, Activity, LogOut, Loader2, MapPin, Mail, Phone, BookOpen, Clock, ChevronRight, X, Trash2 } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface SubscriptionData {
  first_name: string;
  last_name: string;
  email: string;
  phone_number: string;
  street_address: string;
  city: string;
  zip_code: string;
  membership_plan: string;
  subscription_status: string;
  created_at: string;
}

interface SavedWorkout {
    id: string;
    goal: string;
    level: string;
    plan_content: string;
    created_at: string;
}

interface DashboardProps {
  onNavigate: (page: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ onNavigate }) => {
  const [loading, setLoading] = useState(true);
  const [subData, setSubData] = useState<SubscriptionData | null>(null);
  const [savedWorkouts, setSavedWorkouts] = useState<SavedWorkout[]>([]);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [selectedWorkout, setSelectedWorkout] = useState<SavedWorkout | null>(null);

  useEffect(() => {
    fetchData();
  }, [onNavigate]);

  const fetchData = async () => {
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        onNavigate('login');
        return;
      }

      setUserEmail(user.email || '');

      // Fetch Subscriptions
      const { data: sData } = await supabase
        .from('gym_subscriptions')
        .select('*')
        .eq('email', user.email)
        .order('created_at', { ascending: false })
        .limit(1)
        .single();

      if (sData) setSubData(sData);

      // Fetch Saved Workouts
      const { data: wData } = await supabase
        .from('user_workouts')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (wData) setSavedWorkouts(wData);

    } catch (error) {
      console.error('Dashboard fetch error:', error);
    } finally {
      setLoading(false);
    }
  };

  const deleteWorkout = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm('Delete this routine?')) return;
    try {
        const { error } = await supabase.from('user_workouts').delete().eq('id', id);
        if (error) throw error;
        setSavedWorkouts(prev => prev.filter(w => w.id !== id));
    } catch (err) {
        console.error("Delete error:", err);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    onNavigate('home');
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-950">
        <Loader2 className="w-10 h-10 text-lime-400 animate-spin" />
      </div>
    );
  }

  return (
    <section className="min-h-screen bg-zinc-950 pt-28 pb-16 px-4 selection:bg-lime-500/30">
      <div className="container mx-auto max-w-7xl">
        <div className="flex flex-col md:flex-row justify-between items-end mb-12 border-b border-zinc-900 pb-8">
            <div>
                <h1 className="text-5xl font-heading font-bold text-white mb-2 tracking-tighter">
                    ATHLETE <span className="text-lime-400">HUB</span>
                </h1>
                <p className="text-zinc-500 font-medium">Clearance Level: <span className="text-white uppercase font-black tracking-widest text-xs">{subData?.membership_plan || 'Candidate'}</span></p>
            </div>
            <button 
                onClick={handleLogout}
                className="mt-6 md:mt-0 flex items-center gap-2 text-zinc-600 hover:text-red-500 transition-all uppercase font-black text-[10px] tracking-[0.2em] bg-zinc-900 px-5 py-2.5 rounded-xl border border-zinc-800"
            >
                <LogOut className="w-4 h-4" /> Terminate Session
            </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            {/* Profile Section */}
            <div className="space-y-8">
                <motion.div 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="bg-zinc-900 border border-zinc-800 rounded-3xl p-8 shadow-2xl relative overflow-hidden group"
                >
                    <div className="absolute top-0 right-0 p-16 bg-lime-500/5 blur-3xl rounded-full"></div>
                    <div className="relative z-10">
                        <div className="flex items-center gap-5 mb-10">
                            <div className="w-16 h-16 bg-zinc-950 rounded-2xl flex items-center justify-center border border-zinc-800 text-lime-400 group-hover:border-lime-500/50 transition-colors">
                                <User className="w-8 h-8" />
                            </div>
                            <div>
                                <h3 className="text-2xl font-heading font-bold text-white">{subData?.first_name || 'Anonymous'}</h3>
                                <p className="text-xs text-zinc-500 font-mono">{userEmail}</p>
                            </div>
                        </div>

                        <div className="space-y-5">
                            <DetailItem icon={Phone} value={subData?.phone_number || 'No contact uplink'} />
                            <DetailItem icon={MapPin} value={subData?.street_address ? `${subData.street_address}, ${subData.city}` : 'No HQ Address'} />
                        </div>
                    </div>
                </motion.div>

                {/* Subscription Status Card */}
                <motion.div 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-zinc-900 border border-zinc-800 rounded-3xl p-8 shadow-2xl"
                >
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-[10px] font-black uppercase text-zinc-500 tracking-[0.2em]">Deployment Status</h3>
                        <div className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                            subData?.subscription_status === 'active' 
                            ? 'bg-lime-500/10 text-lime-400 border-lime-500/20' 
                            : 'bg-red-500/10 text-red-400 border-red-500/20'
                        }`}>
                            {subData?.subscription_status || 'Inactive'}
                        </div>
                    </div>
                    <div className="space-y-4">
                        <div className="flex items-center justify-between p-4 bg-zinc-950 rounded-2xl border border-zinc-800">
                             <div className="flex items-center gap-3">
                                <Calendar className="w-5 h-5 text-cyan-500" />
                                <span className="text-xs text-zinc-400">Enlisted</span>
                             </div>
                             <span className="text-xs font-bold text-white">{subData?.created_at ? new Date(subData.created_at).toLocaleDateString() : 'N/A'}</span>
                        </div>
                        <div className="flex items-center justify-between p-4 bg-zinc-950 rounded-2xl border border-zinc-800">
                             <div className="flex items-center gap-3">
                                <CreditCard className="w-5 h-5 text-purple-500" />
                                <span className="text-xs text-zinc-400">Next Bill</span>
                             </div>
                             <span className="text-xs font-bold text-white">Manual</span>
                        </div>
                    </div>
                </motion.div>
            </div>

            {/* Content Section: Workouts */}
            <div className="lg:col-span-2 space-y-10">
                <div className="flex items-center justify-between">
                    <h2 className="text-3xl font-heading font-bold text-white tracking-tight flex items-center gap-3">
                        <BookOpen className="text-lime-400" /> ROUTINE <span className="text-zinc-600">LIBRARY</span>
                    </h2>
                    <button onClick={() => onNavigate('ai-coach')} className="text-[9px] font-black uppercase bg-lime-500 text-black px-4 py-2 rounded-lg tracking-widest hover:scale-105 transition-transform">
                        New Brief
                    </button>
                </div>

                {savedWorkouts.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {savedWorkouts.map((workout, idx) => (
                            <motion.div 
                                key={workout.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: idx * 0.05 }}
                                onClick={() => setSelectedWorkout(workout)}
                                className="bg-zinc-900 border border-zinc-800 p-6 rounded-3xl hover:border-zinc-600 transition-all group cursor-pointer relative"
                            >
                                <button 
                                    onClick={(e) => deleteWorkout(workout.id, e)}
                                    className="absolute top-4 right-4 p-2 text-zinc-700 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                                >
                                    <Trash2 size={16} />
                                </button>
                                <div className="flex items-center gap-3 mb-4">
                                    <div className="w-8 h-8 rounded-lg bg-lime-500/10 flex items-center justify-center text-lime-400">
                                        <Activity size={18} />
                                    </div>
                                    <span className="text-[10px] font-black uppercase text-zinc-500 tracking-widest">{workout.level}</span>
                                </div>
                                <h4 className="text-xl font-heading font-bold text-white mb-2 group-hover:text-lime-400 transition-colors">{workout.goal}</h4>
                                <div className="flex items-center justify-between mt-6">
                                    <div className="flex items-center gap-2 text-[10px] text-zinc-600 font-bold">
                                        <Clock size={12} /> {new Date(workout.created_at).toLocaleDateString()}
                                    </div>
                                    <ChevronRight size={16} className="text-zinc-700 group-hover:translate-x-1 group-hover:text-white transition-all" />
                                </div>
                            </motion.div>
                        ))}
                    </div>
                ) : (
                    <div className="bg-zinc-900/50 border-2 border-dashed border-zinc-800 p-16 rounded-3xl text-center">
                        <BookOpen className="w-12 h-12 text-zinc-800 mx-auto mb-4" />
                        <p className="text-zinc-600 uppercase font-black text-[10px] tracking-[0.2em]">Empty Library</p>
                        <button onClick={() => onNavigate('ai-coach')} className="mt-4 text-lime-400 text-[10px] font-bold uppercase underline">Consult AI Coach</button>
                    </div>
                )}
            </div>
        </div>
      </div>

      {/* Routine Detail Modal */}
      <AnimatePresence>
        {selectedWorkout && (
            <>
                <motion.div 
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    onClick={() => setSelectedWorkout(null)}
                    className="fixed inset-0 bg-black/90 backdrop-blur-md z-[100]"
                />
                <motion.div 
                    initial={{ x: '100%' }}
                    animate={{ x: 0 }}
                    exit={{ x: '100%' }}
                    className="fixed top-0 right-0 h-full w-full md:w-[600px] bg-zinc-950 border-l border-zinc-900 z-[101] shadow-2xl p-8 md:p-12 overflow-y-auto"
                >
                    <button onClick={() => setSelectedWorkout(null)} className="absolute top-8 left-8 text-zinc-600 hover:text-white transition-colors">
                        <X size={32} />
                    </button>
                    <div className="mt-16">
                        <span className="text-[10px] font-black uppercase text-lime-500 tracking-[0.3em] mb-4 block">Deployment Protocol</span>
