const AICoach: React.FC = () => {
  const [goal, setGoal] = useState('');
  const [level, setLevel] = useState('Beginner');
  const [response, setResponse] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [user, setUser] = useState<any>(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });
  }, []);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!goal) return;

    setLoading(true);
    setResponse('');
    setSaveSuccess(false);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        You are 'Fitness Hub AI', an elite fitness coach. 
        Goal: "${goal}".
        Level: "${level}".

        Create a high-intensity, professional daily workout. 
        Format your response CLEARLY with the following structure:
        ### [Workout Name]
        **Focus:** [Goal]
        ---
        #### Phase 1: Warmup
        * Exercise 1 (Sets x Reps)
        #### Phase 2: Main Session
        * Exercise 2 (Sets x Reps)
        #### Phase 3: Cool Down
        * Exercise 3
        ---
        **Coach's Tip:** [Intense motivational tip]
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });

      setResponse(result.text || "Could not generate plan.");
    } catch (error) {
      console.error("AI Error:", error);
      setResponse("System overload. Please check your connection.");
    } finally {
      setLoading(false);
    }
  };

  const saveWorkout = async () => {
    if (!user || !response) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from('user_workouts')
        .insert([{
          user_id: user.id,
          goal: goal,
          plan_content: response,
          level: level,
          created_at: new Date().toISOString()
        }]);

      if (error) throw error;
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error("Save error:", err);
    } finally {
      setSaving(false);
    }
  };

  return (
