      </div>

      <div className="container mx-auto px-4 relative z-10">
        <div className="text-center mb-12 md:mb-16">
            <motion.div 
                initial={{ opacity: 0, scale: 0.9 }}
                whileInView={{ opacity: 1, scale: 1 }}
                className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-zinc-900 border border-zinc-800 mb-6 shadow-xl"
            >
                <Sparkles className="w-4 h-4 text-lime-400" />
                <span className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em]">Neural Coaching Engine</span>
            </motion.div>
            <h2 className="text-4xl md:text-7xl font-heading font-bold text-white mb-6 tracking-tighter">
                AI <span className="text-transparent bg-clip-text bg-gradient-to-r from-lime-400 to-cyan-400">COMMANDER</span>
            </h2>
            <p className="text-zinc-500 max-w-2xl mx-auto text-base md:text-lg">
