import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, Eye, EyeOff, ShieldCheck, Mail, Lock } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface LoginProps {
    onNavigate: (page: string) => void;
}

const Login: React.FC<LoginProps> = ({ onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{email?: string, password?: string}>({});

  const validateForm = () => {
    const errors: {email?: string, password?: string} = {};
    let isValid = true;

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) {
      errors.email = 'Email is required';
      isValid = false;
    } else if (!emailRegex.test(email)) {
      errors.email = 'Enter a valid email address';
      isValid = false;
    }

    if (!password) {
      errors.password = 'Password is required';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');
    if (!validateForm()) return;
    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(), 
        password,
      });

      if (error) throw error;

      const user = data.user;
      const isAdmin = user?.user_metadata?.is_admin === true || 
                      user?.app_metadata?.role === 'admin' ||
                      email.toLowerCase().includes('admin@myfitnesshub.fit');

      if (isAdmin) {
          onNavigate('admin-dashboard');
      } else {
          onNavigate('dashboard');
      }

    } catch (err: any) {
      console.error('Login error:', err);
      if (err.message.toLowerCase().includes('invalid login credentials')) {
         setGlobalError('Access denied. Double check your credentials or verify your email.');
      } else if (err.message.includes('Email not confirmed')) {
         setGlobalError('Email verification required. Check your inbox.');
      } else {
         setGlobalError(err.message || 'Login failed. Try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4 py-12 relative overflow-hidden">
      <div className="absolute top-[-20%] left-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="w-full max-w-md bg-zinc-900 border border-zinc-800 p-6 sm:p-10 rounded-3xl shadow-2xl relative z-10"
      >
        <button onClick={() => onNavigate('home')} className="absolute top-6 left-6 text-zinc-500 hover:text-white transition-colors">
            <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="text-center mb-8 mt-4">
            <div className="flex justify-center mb-4">
                <Dumbbell className="w-12 h-12 text-lime-400" />
            </div>
            <h2 className="text-3xl font-heading font-bold text-white mb-2 uppercase tracking-tight">Access Hub</h2>
            <p className="text-zinc-500 text-xs font-bold uppercase tracking-widest">Login to your command center</p>
        </div>

        {globalError && (
            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/50 rounded-xl flex items-start gap-3 text-red-400 text-xs leading-relaxed">
                <AlertCircle className="w-5 h-5 mt-0.5 flex-shrink-0" /> 
                <span>{globalError}</span>
            </div>
        )}

        <form onSubmit={handleLogin} className="space-y-5">
            <div>
                <label className="block text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em] mb-2 ml-1">Email Address</label>
                <div className="relative">
                    <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-700" />
                    <input 
                        type="email" 
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className={`w-full bg-zinc-950 border rounded-2xl p-4 pl-12 text-white focus:outline-none transition-all ${fieldErrors.email ? 'border-red-500' : 'border-zinc-800 focus:border-lime-500'}`}
                        placeholder="you@example.com"
                    />
                </div>
                {fieldErrors.email && <p className="text-red-400 text-[10px] mt-1.5 font-bold uppercase ml-1">{fieldErrors.email}</p>}
            </div>
            <div>
                <label className="block text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em] mb-2 ml-1">Secret Key</label>
                <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-700" />
                    <input 
                        type={showPassword ? "text" : "password"}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className={`w-full bg-zinc-950 border rounded-2xl p-4 pl-12 pr-12 text-white focus:outline-none transition-all ${fieldErrors.password ? 'border-red-500' : 'border-zinc-800 focus:border-lime-500'}`}
                        placeholder="••••••••"
                    />
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-zinc-600 hover:text-white transition-colors">
                        {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                    </button>
                </div>
                {fieldErrors.password && <p className="text-red-400 text-[10px] mt-1.5 font-bold uppercase ml-1">{fieldErrors.password}</p>}
            </div>

            <div className="flex justify-end">
                <button type="button" onClick={() => onNavigate('forgot-password')} className="text-[10px] text-lime-400 font-black uppercase tracking-widest hover:underline">
                    Password Recovery
                </button>
            </div>

            <button type="submit" disabled={loading} className="w-full bg-lime-500 text-black font-black uppercase py-4 rounded-2xl hover:bg-lime-400 transition-all shadow-xl flex items-center justify-center gap-2 disabled:opacity-70 tracking-widest">
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Enter Profile'}
            </button>
        </form>

        <div className="mt-8 text-center text-[10px] text-zinc-500 font-black uppercase tracking-widest">
            New Prospect? <button onClick={() => onNavigate('signup')} className="text-white hover:text-lime-400 underline">Register Now</button>
        </div>

        <div className="mt-8 pt-6 border-t border-zinc-800 text-center">
             <button onClick={() => onNavigate('admin-login')} className="text-[10px] uppercase font-black text-zinc-700 hover:text-red-500 transition-colors flex items-center justify-center gap-2 mx-auto tracking-widest">
                <ShieldCheck className="w-4 h-4" /> Administrator Protocol
            </button>
        </div>
      </motion.div>
    </div>
  );
};

export default Login;

