import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, Eye, EyeOff, ShieldCheck, Mail, Lock } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface LoginProps {
    onNavigate: (page: string) => void;
}

const Login: React.FC<LoginProps> = ({ onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [fieldErrors, setFieldErrors] = useState<{email?: string, password?: string}>({});

  const validateForm = () => {
    const errors: {email?: string, password?: string} = {};
    let isValid = true;

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email) {
      errors.email = 'Email is required';
      isValid = false;
    } else if (!emailRegex.test(email)) {
      errors.email = 'Enter a valid email address';
      isValid = false;
    }

    if (!password) {
      errors.password = 'Password is required';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');
    if (!validateForm()) return;
    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email: email.trim(), 
        password,
      });

      if (error) throw error;

      const user = data.user;
      const isAdmin = user?.user_metadata?.is_admin === true || 
                      user?.app_metadata?.role === 'admin' ||
                      email.toLowerCase().includes('admin@myfitnesshub.fit');

      if (isAdmin) {
          onNavigate('admin-dashboard');
      } else {
          onNavigate('dashboard');
      }

    } catch (err: any) {
      console.error('Login error:', err);
      if (err.message.toLowerCase().includes('invalid login credentials')) {
         setGlobalError('Access denied. Double check your credentials or verify your email.');
      } else if (err.message.includes('Email not confirmed')) {
         setGlobalError('Email verification required. Check your inbox.');
      } else {
         setGlobalError(err.message || 'Login failed. Try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4 py-16 relative overflow-hidden">
      {/* Background Glows */}
      <div className="absolute top-[-20%] left-[-10%] w-[600px] h-[600px] bg-lime-500/10 rounded-full blur-[120px] pointer-events-none"></div>
      <div className="absolute bottom-[-20%] right-[-10%] w-[600px] h-[600px] bg-cyan-500/5 rounded-full blur-[120px] pointer-events-none"></div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md bg-zinc-900 border border-zinc-800 p-8 sm:p-12 rounded-[2.5rem] shadow-[0_30px_60px_rgba(0,0,0,0.6)] relative z-10"
      >
        <button 
            onClick={() => onNavigate('home')} 
            className="absolute top-8 left-8 text-zinc-500 hover:text-white transition-colors p-2"
        >
            <ArrowLeft className="w-6 h-6" />
        </button>

        <div className="text-center mb-10 mt-6">
            <div className="flex justify-center mb-6">
                <div className="w-16 h-16 bg-lime-500/10 rounded-2xl flex items-center justify-center border border-lime-500/20 shadow-inner">
                    <Dumbbell className="w-8 h-8 text-lime-400" />
                </div>
            </div>
            <h2 className="text-4xl font-heading font-bold text-white mb-2 uppercase tracking-tighter">Command <span className="text-lime-400">Hub</span></h2>
            <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em]">Authorize Session</p>
        </div>

        {globalError && (
            <div className="mb-8 p-5 bg-red-500/10 border border-red-500/30 rounded-2xl flex items-start gap-3 text-red-400 text-xs leading-relaxed animate-pulse">
                <AlertCircle className="w-5 h-5 mt-0.5 flex-shrink-0" /> 
                <span className="font-bold">{globalError}</span>
            </div>
        )}

        <form onSubmit={handleLogin} className="space-y-6">
            <div>
                <label className="block text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em] mb-3 ml-2">Identity Uplink</label>
                <div className="relative group">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-700 group-focus-within:text-lime-500 transition-colors" />
                    <input 
                        type="email" 
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className={`w-full bg-zinc-950 border-2 rounded-2xl p-5 pl-14 text-white focus:outline-none transition-all text-sm md:text-base ${fieldErrors.email ? 'border-red-500' : 'border-zinc-800 focus:border-lime-500'}`}
                        placeholder="you@domain.fit"
                    />
                </div>
                {fieldErrors.email && <p className="text-red-400 text-[10px] mt-2 font-black uppercase ml-2">{fieldErrors.email}</p>}
            </div>
            <div>
                <label className="block text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em] mb-3 ml-2">Secret Code</label>
                <div className="relative group">
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-700 group-focus-within:text-lime-500 transition-colors" />
                    <input 
                        type={showPassword ? "text" : "password"}
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className={`w-full bg-zinc-950 border-2 rounded-2xl p-5 pl-14 pr-14 text-white focus:outline-none transition-all text-sm md:text-base ${fieldErrors.password ? 'border-red-500' : 'border-zinc-800 focus:border-lime-500'}`}
                        placeholder="••••••••"
                    />
                    <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-5 top-1/2 -translate-y-1/2 text-zinc-600 hover:text-white transition-colors">
                        {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                    </button>
                </div>
                {fieldErrors.password && <p className="text-red-400 text-[10px] mt-2 font-black uppercase ml-2">{fieldErrors.password}</p>}
            </div>

            <div className="flex justify-end pr-2">
                <button type="button" onClick={() => onNavigate('forgot-password')} className="text-[10px] text-zinc-500 hover:text-lime-400 font-black uppercase tracking-widest transition-colors">
                    Lost Credentials?
                </button>
            </div>

            <button type="submit" disabled={loading} className="w-full bg-lime-500 text-black font-black uppercase py-5 rounded-2xl hover:bg-lime-400 transition-all shadow-xl flex items-center justify-center gap-3 disabled:opacity-70 tracking-[0.2em] text-sm active:scale-95">
                {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'AUTHENTICATE'}
            </button>
        </form>

        <div className="mt-12 text-center text-[10px] text-zinc-600 font-black uppercase tracking-widest">
            New Prospect? <button onClick={() => onNavigate('signup')} className="text-white hover:text-lime-400 underline transition-colors">Register for Hub</button>
        </div>

        <div className="mt-10 pt-8 border-t border-zinc-800 text-center">
             <button onClick={() => onNavigate('admin-login')} className="text-[9px] uppercase font-black text-zinc-700 hover:text-red-500 transition-all flex items-center justify-center gap-3 mx-auto tracking-[0.3em]">
                <ShieldCheck className="w-4 h-4" /> Admin Protocol
            </button>
        </div>
      </motion.div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Dumbbell, ArrowLeft, Loader2, AlertCircle, CheckCircle, Mail, Eye, EyeOff, ShieldCheck, LogIn, Shield, User, Zap } from 'lucide-react';
import { supabase } from '../lib/supabaseClient';

interface SignupProps {
    onNavigate: (page: string) => void;
}

const Signup: React.FC<SignupProps> = ({ onNavigate }) => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [globalError, setGlobalError] = useState('');
  const [isAlreadyRegistered, setIsAlreadyRegistered] = useState(false);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [successState, setSuccessState] = useState<'none' | 'confirmation_required' | 'complete'>('none');
  const [passwordStrength, setPasswordStrength] = useState(0);

  const calculateStrength = (pass: string) => {
    let score = 0;
    if (pass.length >= 6) score++;
    if (pass.length >= 10) score++;
    if (/[A-Z]/.test(pass)) score++;
    if (/[0-9]/.test(pass)) score++;
    return score; // Max 4
  };

  const validateForm = () => {
    const errors: Record<string, string> = {};
    let isValid = true;

    if (!formData.firstName.trim() || formData.firstName.length < 2) {
      errors.firstName = 'First name required';
      isValid = false;
    }
    if (!formData.lastName.trim() || formData.lastName.length < 2) {
      errors.lastName = 'Last name required';
      isValid = false;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      errors.email = 'Valid email required';
      isValid = false;
    }
    if (formData.password.length < 6) {
      errors.password = 'Min 6 characters';
      isValid = false;
    }

    setFieldErrors(errors);
    return isValid;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
    if (fieldErrors[name]) setFieldErrors(prev => ({ ...prev, [name]: '' }));
    if (globalError) setGlobalError('');
    if (isAlreadyRegistered) setIsAlreadyRegistered(false);

    if (name === 'password') {
      setPasswordStrength(calculateStrength(value));
    }
  };

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    setGlobalError('');
    setIsAlreadyRegistered(false);

    if (!validateForm()) return;

    setLoading(true);

    try {
      const { data, error } = await supabase.auth.signUp({
        email: formData.email.trim(),
        password: formData.password,
        options: {
          data: {
            first_name: formData.firstName,
            last_name: formData.lastName,
          },
        },
      });

      if (error) {
        if (error.message.toLowerCase().includes('already registered')) {
            setIsAlreadyRegistered(true);
            throw new Error('An account with this email already exists.');
        }
        throw error;
      }

      if (data?.user && !data?.session) {
        setSuccessState('confirmation_required');
      } else {
        setSuccessState('complete');
        setTimeout(() => onNavigate('dashboard'), 2000);
      }

    } catch (err: any) {
      console.error('Signup error:', err);
      setGlobalError(err.message || 'Failed to create account. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  if (successState === 'confirmation_required') {
      return (
        <div className="min-h-screen flex items-center justify-center bg-zinc-950 px-4 py-20">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0 }} 
                animate={{ scale: 1, opacity: 1 }} 
                className="bg-zinc-900 border border-lime-500/30 p-10 md:p-16 rounded-[3rem] text-center max-w-xl w-full shadow-2xl"
            >
                <div className="w-24 h-24 bg-lime-500/10 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-lime-500/20">
                    <Mail className="w-12 h-12 text-lime-400 animate-bounce" />
                </div>
                <h2 className="text-4xl font-heading font-bold text-white mb-6 uppercase tracking-tighter">Verify Your <span className="text-lime-400">Signal</span></h2>
                <p className="text-zinc-400 text-lg mb-10 leading-relaxed font-medium">
                    We've sent an encrypted verification link to <span className="text-white font-black underline">{formData.email}</span>.<br/><br/>
                    Activate your profile via the link to complete enlistment.
                </p>
                <div className="space-y-6">
                    <button onClick={() => onNavigate('login')} className="w-full bg-white text-black font-black uppercase py-5 rounded-2xl hover:bg-lime-500 transition-all tracking-[0.2em] shadow-2xl">
                        RETURN TO LOGIN
                    </button>
