    if (!user || !response) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from('user_workouts')
        .insert([{
          user_id: user.id,
          goal: goal,
          plan_content: response,
          level: level,
          created_at: new Date().toISOString()
        }]);

      if (error) throw error;
      setSaveSuccess(true);
