            <div className="flex justify-center mb-6">
                <div className="w-16 h-16 bg-cyan-500/10 rounded-2xl flex items-center justify-center border border-cyan-500/20">
                    <Zap className="w-8 h-8 text-cyan-400" />
                </div>
            </div>
            <h2 className="text-4xl md:text-5xl font-heading font-bold text-white mb-3 uppercase tracking-tighter">New <span className="text-cyan-400">Enlistment</span></h2>
            <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em]">Initiate Performance Protocol</p>
        </div>

        {globalError && (
            <div className={`mb-10 p-6 rounded-2xl flex items-start gap-4 text-sm ${isAlreadyRegistered ? 'bg-cyan-500/10 border border-cyan-500/30 text-cyan-400' : 'bg-red-500/10 border border-red-500/30 text-red-400'} animate-pulse`}>
                <AlertCircle className="w-6 h-6 flex-shrink-0 mt-0.5" />
