                </div>
                <div>
                    <label className="block text-zinc-500 text-[10px] font-black uppercase tracking-[0.2em] mb-3 ml-2">Last Name</label>
                    <input 
                        name="lastName" 
                        type="text" 
                        value={formData.lastName} 
                        onChange={handleChange} 
                        className={`w-full bg-zinc-950 border-2 rounded-2xl p-4 text-white placeholder-zinc-800 focus:outline-none transition-all ${fieldErrors.lastName ? 'border-red-500' : 'border-zinc-800 focus:border-cyan-500'}`} 
                        placeholder="Doe" 
                    />
                    {fieldErrors.lastName && <p className="text-red-400 text-[10px] mt-2 font-black uppercase ml-2">{fieldErrors.lastName}</p>}
